window.CSAE=window.CSAE||{};window.CSAE.laboratory=[{"week":1,"title":"HTML and CSS warm-up","focus":"Set up your tools, build a responsive page, inspect the Network tab","duration":"3 hours","file":"Week_01_Laboratory_How_the_web_works.pptx","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Set up VS Code, Git and Developer Tools. Then build a static, responsive \"Campus Notices\" page by hand with semantic HTML and flexbox, and inspect how the browser loads it. This is the page you will later make dynamic.",false]],[["Deliverable. ",true],["Lab 1 output: a folder with index.html and styles.css, plus a screenshot of the Network tab showing both files loading with status 200.",false]]]},{"k":"callout","t":"Start from this skeleton:"},{"k":"code","t":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Campus Notices</title>\n  <link rel=\"stylesheet\" href=\"styles.css\">\n</head>\n<body>\n  <header>\n    <h1>Campus Notices</h1>\n  </header>\n  <main>\n    <article class=\"notice\">\n      <h2>Library hours extended</h2>\n      <p>The library stays open until 9 PM during midterm week.</p>\n    </article>\n  </main>\n  <footer>\n    <p>College of Computer Science, DMMMSU-SLUC</p>\n  </footer>\n</body>\n</html>","lang":"xml"},{"k":"callout","t":"Answer these three inspection questions in a comment at the top of your HTML file:"},{"k":"list","items":[[["What status code did index.html return, and what does it mean?",false]],[["What is the Content-Type of styles.css?",false]],[["What status code appears when you misspell styles.css in the link tag, and what happens to the page?",false]]]}],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: HTML and CSS warm-up","tag":null,"kind":"divider","sub":"Follow the steps in order.","id":"step-by-step-guide-html-and-css-warm-up"},{"kind":"step","title":"Set up your tools","tag":"STEP 1","step":1,"blocks":[{"k":"list","items":[[["Install VS Code and Git if they are not on your computer yet. Use Chrome, Edge or Firefox as your browser.",false]],[["Open VS Code, then choose Terminal, then New Terminal.",false]],[["Check that Git works with the first command below. Then tell Git who you are with the other two, using your own name and email.",false]]]},{"k":"code","t":"git --version\ngit config --global user.name \"Your Name\"\ngit config --global user.email \"you@example.com\"","lang":"bash"},{"k":"list","items":[[["In your browser, press F12 to open Developer Tools. Find the Elements tab and the Network tab. You will use both in this lab.",false]]]}],"extra":["You should see a line that starts with git version, and a Developer Tools panel with an Elements tab and a Network tab."],"id":"set-up-your-tools"},{"title":"Create the project","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["Make a new folder called campus-notices on your computer.",false]],[["Open VS Code, choose File, then Open Folder, and pick it.",false]],[["Use the New File button in the sidebar to create index.html and styles.css.",false]]]}],"extra":["You should see both files listed in the Explorer."],"id":"create-the-project"},{"title":"Paste the skeleton and open it","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"list","items":[[["Copy the skeleton from the lab brief at the top of this page into index.html and save (Ctrl+S).",false]],[["Open the file in your browser (double-click it, or right-click it in VS Code and choose Open with Live Server if you have that extension).",false]]]}],"extra":["You should see the heading \"Campus Notices\", one notice, and a footer, with no styling yet."],"id":"paste-the-skeleton-and-open-it"},{"title":"Add two more notices","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["Copy the whole <article class=\"notice\">...</article> block and paste it twice below the first one.",false]],[["Change the <h2> and <p> text in each copy to real campus news.",false]],[["Save and refresh.",false]]]}],"extra":["You should see three notices. If one is missing or looks odd, check that every opening tag has its closing tag."],"id":"add-two-more-notices"},{"title":"Make the HTML more meaningful","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["Inside each notice, add a date and a category:",false]]]},{"k":"code","t":"<article class=\"notice\">\n  <h2>Library hours extended</h2>\n  <p class=\"meta\">\n    <time datetime=\"2026-10-12\">12 October 2026</time> · <span class=\"tag\">Academic</span>\n  </p>\n  <p>The library stays open until 9 PM during midterm week.</p>\n</article>","lang":"xml"},{"k":"callout","t":"Save and refresh. You should see the date and category under each title. Semantic tags such as header, main, article, time and footer tell the browser and screen readers what each part is."}],"id":"make-the-html-more-meaningful"},{"title":"Style the page in styles.css","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["Add the rules below one block at a time, saving and refreshing after each, so you can see what each one does.",false]]]},{"k":"code","t":"body {\n  font-family: system-ui, sans-serif;\n  margin: 0;\n  background: #f4f7fa;\n  color: #1f2933;\n}\n\nheader {\n  background: #1d4e89;","lang":"css"},{"k":"code","t":"  color: white;\n  padding: 16px 24px;\n}\n\nmain {\n  max-width: 720px;\n  margin: 24px auto;\n  padding: 0 16px;\n  display: flex;          /* flexbox: lay the children out in one direction */\n  flex-direction: column; /* stack them top to bottom */\n  gap: 16px;              /* space between the notices */\n}","lang":"css"},{"k":"code","t":".notice {\n  background: white;\n  border: 1px solid #d9e2ec;\n  border-radius: 8px;\n  padding: 16px;\n}\n\n.tag {\n  background: #e0ecf8;\n  border-radius: 4px;\n  padding: 2px 8px;\n  font-size: 0.85rem;\n}","lang":"css"},{"k":"code","t":"footer {\n  text-align: center;\n  padding: 16px;\n}","lang":"css"},{"k":"callout","t":"You should see a blue header, a centred column, and white cards with rounded corners. Each card has content, then padding, then a border, then margin around it. That is the box model. Right-click a card, choose Inspect, and find the box diagram in the Styles panel."}],"id":"style-the-page-in-styles-css"},{"title":"Make it responsive","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"list","items":[[["Add this at the bottom of styles.css:",false]]]},{"k":"code","t":"@media (max-width: 600px) {\n  header { padding: 12px 16px; }\n  main { margin: 12px auto; }\n}","lang":"css"},{"k":"callout","t":"Press F12, then Ctrl+Shift+M to turn on the device toolbar and choose a phone size. You should see the layout still fitting the screen with no sideways scrolling."}],"id":"make-it-responsive"},{"title":"Inspect the page","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"list","items":[[["Press F12 and open the Network tab, then reload the page (Ctrl+R).",false]],[["You should see two rows, index.html and styles.css, each with status 200.",false]],[["Click styles.css and look at the Headers panel for its Content-Type.",false]]]}],"extra":["Now misspell styles.css in the <link> tag, reload, and watch what happens (a 404 row appears and the page loses its style). Fix the spelling again. Write your answers to the three inspection questions in an HTML comment at the top of index.html."],"id":"inspect-the-page"},{"title":"Take your screenshot and show your instructor","tag":"STEP 9","kind":"step","step":9,"blocks":[{"k":"list","items":[[["Take a screenshot of the Network tab showing both files with status 200.",false]]]}],"id":"take-your-screenshot-and-show-your-instructor"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["Git is installed and `git --version` shows a version number.",false]],[["The page has a header, a main area with three notices, and a footer.",false]],[["The HTML uses semantic elements, and the CSS uses the box model, flexbox and one media query.",false]],[["Your three inspection answers are in a comment at the top of index.html.",false]],[["You have the Network-tab screenshot.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Add a dark theme using CSS custom properties (variables) and the prefers-color-scheme media query. Switch your computer's theme and confirm that the page changes with no JavaScript."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"syllabus":{"label":"Week 1","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Review and apply semantic HTML and CSS (selectors, box model, flexbox) to structure and style a page.","Describe the client–server model and the request–response cycle.","Read and interpret HTTP requests, responses, headers and status codes.","Use browser Developer Tools to inspect network traffic.","Build a simple static, responsive page with HTML and CSS."],"topics":{"lecture":["HTML review: document structure, semantic elements and forms","CSS review: selectors, the cascade, the box model, flexbox, grid and responsive design","Client–server model and the request–response cycle","URLs, DNS, browsers and servers","HTTP methods, headers and status codes","Inspecting traffic with browser Developer Tools","Course orientation and Campus Notices Board overview"],"laboratory":["Set up VS Code, Git and browser Developer Tools","Build a static, responsive HTML/CSS page (semantic HTML, flexbox)","Inspect an HTTP request and response in the Network tab"]},"methods":["Interactive lecture","Visual demonstration (DevTools Network tab)","Guided practice (HTML/CSS review and warm-up)","Flipped learning (pre-reading)"],"resources":["VS Code; Git; Chrome, Edge or Firefox with Developer Tools","Limson (2026), Ch. 1 (How the web works)","Limson (2026), Laboratory manual, Lab 1","Fielding et al. (2022), RFC 9110 (selected sections on HTTP semantics)","Mozilla Developer Network (n.d.), Learn web development: HTML, CSS and HTTP guides","Course slides (HTML and CSS review; How the web works)"],"assessment":["Written quiz: HTML/CSS review, HTTP, requests and responses","Recitation: trace what happens when a URL is opened","Lab 1 output: responsive HTML/CSS page with a Network-tab screenshot"],"sdg":[{"goal":"SDG 4: Quality Education","target":"Target 4.4: By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship.","link":"Understanding how the web works is the entry-point competency for every web and ICT career."},{"goal":"SDG 9: Industry, Innovation and Infrastructure","target":"Target 9.c: Significantly increase access to information and communications technology.","link":"The web is the delivery channel through which access to ICT and information reaches communities."}]},"pptxNote":"The slide file is the earlier version. This page follows the revised syllabus.","slideCount":17,"pptx":"downloads/laboratory/Week_01_Laboratory_How_the_web_works.pptx"},{"week":2,"title":"Modern JavaScript","focus":"JavaScript exercises","duration":"3 hours","file":"Week_02_Laboratory_Modern_JavaScript.pptx","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Practise modern JavaScript on small problems, then combine them into a page that renders and filters a list of notices.",false]],[["Deliverable. ",true],["Lab 2 output: a folder with index.html, main.js and notices.js, running in the browser with no errors in the console.",false]]]}],"extra":["Hint for the search box: listen to the input event, call filter on the array, then render the result again."],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: JavaScript exercises","tag":null,"kind":"divider","sub":"Follow the steps in order.","id":"step-by-step-guide-javascript-exercises"},{"title":"Create the project","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"list","items":[[["Make a folder js-practice with three files: index.html, main.js and notices.js.",false]],[["Put this in index.html:",false]]]},{"k":"code","t":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>JS Practice</title>\n  </head>\n  <body>","lang":"xml"},{"k":"code","t":"    <h1>Campus Notices</h1>\n    <input id=\"search\" placeholder=\"Search notices...\" />\n    <ul id=\"list\"></ul>\n    <script type=\"module\" src=\"main.js\"></script>\n  </body>\n</html>","lang":"xml"},{"k":"callout","t":"Modules do not load when you double-click the file. Open the page with the Live Server extension (right-click index.html, then Open with Live Server), or run npx serve in the folder. You should see the heading and the search box, and no red errors in the Console."}],"id":"create-the-project"},{"title":"Warm-up: arrow functions","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["In main.js, rewrite these three function declarations as arrow functions with the same names:",false]]]},{"k":"code","t":"function double(n) { return n * 2; }\nfunction greet(name) { return \"Hello, \" + name; }\nfunction isLong(text) { return text.length > 20; }","lang":"javascript"},{"k":"callout","t":"Check yourself: double(4) should log 8, greet(\"Ana\") should log Hello, Ana, and isLong(\"short\") should log false. Compare with this answer:"},{"k":"code","t":"const double = (n) => n * 2;\nconst greet = (name) => `Hello, ${name}`;\nconst isLong = (text) => text.length > 20;","lang":"javascript"}],"id":"warm-up-arrow-functions"},{"title":"Array methods","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"list","items":[[["Start with this array of store items:",false]]]},{"k":"code","t":"const items = [\n  { name: \"Coffee sachet\", price: 8 },\n  { name: \"Biscuit\", price: 12 },\n  { name: \"Softdrink\", price: 25 },\n  { name: \"Candy\", price: 2 },\n];","lang":"javascript"},{"k":"callout","t":"Use map, filter and reduce to produce: (a) an array of the names, (b) the items under PHP 20, and (c) the total price. You should log [\"Coffee sachet\", \"Biscuit\", \"Softdrink\", \"Candy\"], then three items (all except Softdrink), then 47. Compare with:"},{"k":"code","t":"const names = items.map((item) => item.name);\nconst cheap = items.filter((item) => item.price < 20);\nconst total = items.reduce((sum, item) => sum + item.price, 0);","lang":"javascript"}],"id":"array-methods"},{"title":"Destructuring and spread","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["Create an object and change one field without changing the original:",false]]]},{"k":"code","t":"const notice = { id: 1, title: \"Library hours\", pinned: false };\nconst { title } = notice;                         // destructuring: pull out one field\nconst pinnedNotice = { ...notice, pinned: true }; // spread: copy, then override\nconsole.log(notice, pinnedNotice);","lang":"javascript"},{"k":"callout","t":"You should see pinned: false in the first object and pinned: true in the second. That proves the original did not change."}],"id":"destructuring-and-spread"},{"title":"Modules","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["In notices.js, move the data and export it:",false]]]},{"k":"code","t":"export const notices = [\n  { id: 1, title: \"Library hours extended\", message: \"Open until 9 PM during midterm week.\" },\n  { id: 2, title: \"Enrollment reminder\", message: \"Last day to add or drop subjects is Friday.\" },\n  { id: 3, title: \"Programming contest\", message: \"Sign up at the CCS office by Monday.\" },\n  { id: 4, title: \"Wi-Fi maintenance\", message: \"The campus network is down Sunday morning.\" },\n];","lang":"javascript"},{"k":"callout","t":"In main.js, import it at the top with import { notices } from \"./notices.js\"; and run console.log(notices);. You should see the four notices in the Console. If you see an error that mentions CORS or file://, you opened the page without a server."}],"id":"modules"},{"title":"Render with the DOM","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["Add this to main.js:",false]]]},{"k":"code","t":"const list = document.querySelector(\"#list\");\n\nfunction render(items) {\n  list.innerHTML = \"\";               // clear the old list first\n  items.forEach((n) => {\n    const li = document.createElement(\"li\");\n    li.textContent = `${n.title}: ${n.message}`;\n    list.appendChild(li);\n  });\n}","lang":"javascript"},{"k":"code","t":"render(notices);","lang":"javascript"},{"k":"callout","t":"You should see four bullet points on the page."}],"id":"render-with-the-dom"},{"title":"Events: search as you type","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"code","t":"const search = document.querySelector(\"#search\");\n\nsearch.addEventListener(\"input\", () => {\n  const text = search.value.toLowerCase();\n  const matches = notices.filter((n) => n.title.toLowerCase().includes(text));\n  render(matches);\n});","lang":"javascript"},{"k":"callout","t":"Type \"wi\" in the box. You should see only the Wi-Fi notice. Clear the box and all four come back."}],"id":"events-search-as-you-type"},{"title":"Clean up and show your instructor","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"list","items":[[["Remove unused console.log lines and make sure the Console has no errors.",false]]]}],"id":"clean-up-and-show-your-instructor"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["The three arrow functions, the array methods and the spread example all work.",false]],[["The data lives in notices.js and is imported into main.js.",false]],[["The list renders from the array, and the search box filters it as you type.",false]],[["The Console shows no errors.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Save the notices in localStorage so the list survives a page refresh. Remember that localStorage stores only strings."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"syllabus":{"label":"Weeks 2 to 3","hours":"Weeks 2 and 3 share one plan: 10 hours in all (lecture 4, laboratory 6)","outcomes":["Write modern JavaScript using ES6+ syntax and modules.","Select and manipulate DOM elements and respond to events.","Explain callbacks, Promises and async/await and use them correctly.","Fetch JSON from a public API and display it with loading and error handling."],"outcomesNote":"Outcomes 1 and 2 are the focus of Week 2. Outcomes 3 and 4 continue in Week 3.","topics":{"lecture":["ES6+: let/const, arrow functions, destructuring, template literals","Modules (import/export)","DOM selection, events and manipulation","Callbacks, Promises and async/await","Fetch API, JSON and error handling with try/catch"],"laboratory":["Complete ES6 and DOM exercises","Fetch and display data from a public API","Handle loading and error cases"]},"methods":["Lecture with live coding","Predict-the-output activity","Problem-based learning (public API task)","Paired programming","Individual lab practice"],"resources":["VS Code; browser Developer Tools; a public REST API","Limson (2026), Chaps. 2–3 (Modern JavaScript; Asynchronous JavaScript)","Limson (2026), Laboratory manual, Labs 2–3","Flanagan (2020), chapters on modules and asynchronous JavaScript","Haverbeke (2018), chapters on the DOM and asynchronous programming","Mozilla Developer Network (n.d.), JavaScript guide"],"assessment":["Quiz 1: ES6 and DOM (Week 2)","Lab 2 output: JavaScript exercises (Week 2)","Quiz 2: Promises and async/await (Week 3)","Lab 3 output: public-API fetch page (Week 3)","Google Classroom activity: debug an async function (Week 3)"],"sdg":[{"goal":"SDG 4: Quality Education","target":"Target 4.4: By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship.","link":"JavaScript is the core language of the web and a high-demand skill for ICT employment."},{"goal":"SDG 9: Industry, Innovation and Infrastructure","target":"Target 9.5: Enhance scientific research and upgrade technological capabilities.","link":"Consuming open APIs trains students to build on existing digital infrastructure and innovate on top of it."}]},"pptxNote":"The slide file is the earlier version. This page follows the revised syllabus.","slideCount":19,"pptx":"downloads/laboratory/Week_02_Laboratory_Modern_JavaScript.pptx"},{"week":3,"title":"Asynchronous JavaScript","focus":"fetch data from a public API","duration":"3 hours","file":"Week_03_Laboratory_Asynchronous_JavaScript.pptx","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Read data from a public API and show it on a web page, with sensible loading and error messages.",false]],[["Deliverable. ",true],["A page that fetches a list of posts from https://jsonplaceholder.typicode.com/posts, shows them as cards, and handles the loading and error cases.",false]]]}],"extra":["Check the Network tab for every request. Find the status code and the response for each."],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: fetch data from a public API","tag":null,"kind":"divider","sub":"Follow the steps in order.","id":"step-by-step-guide-fetch-data-from-a-public-api"},{"title":"Try fetch in the Console","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"list","items":[[["Open any web page, press F12, choose Console, and type:",false]]]},{"k":"code","t":"fetch(\"https://jsonplaceholder.typicode.com/posts/1\")\n  .then((res) => res.json())\n  .then((data) => console.log(data));","lang":"javascript"},{"k":"callout","t":"You should see an object with userId, id, title and body. In the Network tab, find the request and note its status code (200)."}],"id":"try-fetch-in-the-console"},{"title":"Create the project","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["Make a folder fetch-posts with index.html and app.js:",false]]]},{"k":"code","t":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Posts</title>\n  </head>\n  <body>\n    <h1>Posts</h1>\n    <input id=\"search\" placeholder=\"Search by title...\" />\n    <p id=\"status\"></p>\n    <div id=\"posts\"></div>","lang":"xml"},{"k":"code","t":"    <script src=\"app.js\"></script>\n  </body>\n</html>","lang":"xml"},{"k":"callout","t":"Open it in the browser. You should see the heading and the search box."}],"id":"create-the-project"},{"title":"Write loadPosts","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"list","items":[[["In app.js:",false]]]},{"k":"code","t":"const statusEl = document.querySelector(\"#status\");\nconst postsEl = document.querySelector(\"#posts\");\nlet allPosts = [];\n\nasync function loadPosts() {\n  try {\n    const res = await fetch(\"https://jsonplaceholder.typicode.com/posts\");\n    if (!res.ok) throw new Error(`Server answered ${res.status}`);\n    allPosts = await res.json();\n    console.log(allPosts.length); // should print 100\n  } catch (err) {","lang":"javascript"},{"k":"code","t":"    console.error(err);\n  }\n}\n\nloadPosts();","lang":"javascript"},{"k":"callout","t":"You should see 100 in the Console. fetch does not fail on a 404 or 500 by itself, which is why the res.ok check matters."}],"id":"write-loadposts"},{"title":"Show the first 10 posts as cards","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["Add a render function, and call it after the data arrives:",false]]]},{"k":"code","t":"function render(posts) {\n  postsEl.innerHTML = \"\";\n  posts.slice(0, 10).forEach((p) => {\n    const card = document.createElement(\"article\");\n    card.innerHTML = `<h3>${p.title}</h3><p>${p.body}</p>`;\n    postsEl.appendChild(card);\n  });\n}","lang":"javascript"},{"k":"callout","t":"Call render(allPosts); right after allPosts = await res.json();. You should see ten cards on the page."}],"id":"show-the-first-10-posts-as-cards"},{"title":"Loading and error messages","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["Update loadPosts so the user always knows what is happening:",false]]]},{"k":"code","t":"async function loadPosts() {\n  statusEl.textContent = \"Loading...\";\n  try {\n    const res = await fetch(\"https://jsonplaceholder.typicode.com/posts\");\n    if (!res.ok) throw new Error(`Server answered ${res.status}`);\n    allPosts = await res.json();\n    statusEl.textContent = \"\";\n    render(allPosts);\n  } catch (err) {\n    statusEl.textContent = \"Sorry, the posts could not be loaded. Please try again.\";","lang":"javascript"},{"k":"code","t":"  }\n}","lang":"javascript"},{"k":"callout","t":"Reload the page. You should see \"Loading...\" for a moment, then the cards."}],"id":"loading-and-error-messages"},{"title":"Search by title","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"code","t":"document.querySelector(\"#search\").addEventListener(\"input\", (e) => {\n  const text = e.target.value.toLowerCase();\n  render(allPosts.filter((p) => p.title.toLowerCase().includes(text)));\n});","lang":"javascript"},{"k":"callout","t":"Type \"qui\" in the box. You should see only posts whose title contains \"qui\"."}],"id":"search-by-title"},{"title":"Send a POST request","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"list","items":[[["Add this function and call it once from the Console:",false]]]},{"k":"code","t":"async function createPost() {\n  const res = await fetch(\"https://jsonplaceholder.typicode.com/posts\", {\n    method: \"POST\",\n    headers: { \"Content-Type\": \"application/json\" },\n    body: JSON.stringify({ title: \"My post\", body: \"Hello\", userId: 1 }),\n  });\n  console.log(res.status, await res.json());\n}","lang":"javascript"},{"k":"callout","t":"Call createPost() in the Console. You should see 201 and an object containing your title and id: 101. The service pretends to save it, so it will not appear in the list later."}],"id":"send-a-post-request"},{"title":"Test the error path","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"list","items":[[["Misspell the URL (for example postz) and reload.",false]],[["You should see your friendly message, not a blank page.",false]],[["Fix the URL again.",false]]]}],"id":"test-the-error-path"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["The page loads 10 posts as cards and shows \"Loading...\" while waiting.",false]],[["A wrong URL shows your friendly error message.",false]],[["The search box filters by title.",false]],[["You logged a 201 from the POST request, and you can say what the Network tab shows for each request.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Pick another public JSON API (for example, public holidays or weather), read its documentation, and show three useful fields on your page. Add a button that reloads the data."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"slideCount":18,"pptx":"downloads/laboratory/Week_03_Laboratory_Asynchronous_JavaScript.pptx"},{"week":4,"title":"Node.js and npm","focus":"first Node program and package setup","duration":"3 hours","file":"Week_04_Laboratory_Node_js_and_npm.pptx","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Build a small command-line program that stores notices in a JSON file, and set it up as a proper npm project.",false]],[["Deliverable. ",true],["A project folder notices-cli with package.json, a .gitignore, and a program that can add and list notices.",false]]]}],"extra":["Hint for add: read the file, push the new notice onto the array, then write the whole array back with fs.writeFileSync and JSON.stringify(notices, null, 2)."],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: first Node program and package setup","tag":null,"kind":"divider","sub":"Follow the steps in order.","id":"step-by-step-guide-first-node-program-and-packag"},{"title":"Check your tools and create the project","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"code","t":"node -v\nnpm -v\nmkdir notices-cli\ncd notices-cli\nnpm init -y","lang":"bash"},{"k":"callout","t":"You should see two version numbers (Node 18 or newer), and a new package.json in the folder. If node is not found, reinstall Node from nodejs.org and reopen the terminal."}],"id":"check-your-tools-and-create-the-project"},{"title":"Write hello.js","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["Create hello.js:",false]]]},{"k":"code","t":"console.log(\"Hello from Node!\");\nconsole.log(\"Arguments:\", process.argv.slice(2));","lang":"javascript"},{"k":"callout","t":"Run node hello.js one two. You should see Hello from Node! and Arguments: [ 'one', 'two' ]."}],"id":"write-hello-js"},{"title":"Create the data file and read it","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"list","items":[[["Create notices.json:",false]]]},{"k":"code","t":"[\n  { \"id\": 1, \"title\": \"Library hours extended\", \"message\": \"Open until 9 PM during midterm week.\" }\n]","lang":"json"},{"k":"callout","t":"Then create cli.js and read the file with the fs module:"},{"k":"code","t":"const fs = require(\"fs\");\n\nfunction readNotices() {\n  return JSON.parse(fs.readFileSync(\"notices.json\", \"utf8\"));\n}\n\nconsole.log(readNotices());","lang":"javascript"},{"k":"callout","t":"Run node cli.js. You should see the array with one notice."}],"id":"create-the-data-file-and-read-it"},{"title":"Add the list and add commands","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["Replace the contents of cli.js:",false]]]},{"k":"code","t":"const fs = require(\"fs\");\n\nfunction readNotices() {\n  return JSON.parse(fs.readFileSync(\"notices.json\", \"utf8\"));\n}\n\nfunction writeNotices(notices) {\n  fs.writeFileSync(\"notices.json\", JSON.stringify(notices, null, 2));\n}\n\nconst [command, title, message] = process.argv.slice(2);","lang":"javascript"},{"k":"code","t":"\nif (command === \"list\") {\n  readNotices().forEach((n) => console.log(`${n.id}. ${n.title}: ${n.message}`));\n} else if (command === \"add\") {\n  if (!title || !message) {\n    console.log('Usage: node cli.js add \"Title\" \"Message\"');\n  } else {\n    const notices = readNotices();\n    const nextId = notices.length ? notices[notices.length - 1].id + 1 : 1;\n    notices.push({ id: nextId, title, message });\n    writeNotices(notices);\n    console.log(`Added notice ${nextId}.`);","lang":"javascript"},{"k":"code","t":"  }\n} else {\n  console.log('Commands: list | add \"Title\" \"Message\"');\n}","lang":"javascript"},{"k":"callout","t":"Try it:"},{"k":"code","t":"node cli.js list\nnode cli.js add \"Enrollment reminder\" \"Last day to add or drop is Friday.\"\nnode cli.js list","lang":"bash"},{"k":"callout","t":"You should see Added notice 2. and then both notices listed. Open notices.json and confirm the new notice is saved in the file."}],"id":"add-the-list-and-add-commands"},{"title":"Install nodemon and add scripts","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"code","t":"npm install --save-dev nodemon","lang":"bash"},{"k":"callout","t":"Open package.json and set the scripts section:"},{"k":"code","t":"\"scripts\": {\n  \"start\": \"node server.js\",\n  \"dev\": \"nodemon server.js\"\n}","lang":"javascript"},{"k":"callout","t":"You should see a devDependencies section containing nodemon, and a new node_modules folder."}],"id":"install-nodemon-and-add-scripts"},{"title":"Run the plain http server from the lecture","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["Create server.js with the no-library server from the lecture above.",false]],[["Start it with npm run dev, then open http://localhost:3001 in the browser and in Postman.",false]],[["You should see the same answer in both.",false]]]}],"extra":["Change the response text, save, and watch nodemon restart the server by itself. Stop it with Ctrl+C."],"id":"run-the-plain-http-server-from-the-lecture"},{"title":"Add .gitignore and finish","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"list","items":[[["Create a file named .gitignore containing one line, node_modules/.",false]],[["Then show your instructor your package.json, the working list and add commands, and the running server.",false]]]}],"id":"add-gitignore-and-finish"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["node cli.js list and node cli.js add \"T\" \"M\" both work, and notices.json is updated.",false]],[["package.json has start and dev scripts and nodemon in devDependencies.",false]],[["The http server answers in the browser and in Postman.",false]],[[".gitignore lists node_modules/.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Add a delete command to your CLI, and a --pinned flag for add. Print pinned notices first when listing."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"slideCount":16,"pptx":"downloads/laboratory/Week_04_Laboratory_Node_js_and_npm.pptx"},{"week":5,"title":"Express: routing and middleware","focus":"first Express server","duration":"3 hours","file":"Week_05_Laboratory_Express_routing_and_middleware.pptx","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Build a small Express server with several routes and your own middleware, and test it with the browser and Postman.",false]],[["Deliverable. ",true],["A project first-express with at least five working routes, a logger middleware, a static page, and a 404 handler.",false]]]}],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: first Express server","tag":null,"kind":"divider","sub":"Follow the steps in order.","id":"step-by-step-guide-first-express-server"},{"title":"Create the project","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"code","t":"mkdir first-express\ncd first-express\nnpm init -y\nnpm install express\nnpm install --save-dev nodemon","lang":"bash"},{"k":"callout","t":"Open package.json and set the scripts to \"start\": \"node server.js\" and \"dev\": \"nodemon server.js\". You should see express under dependencies and nodemon under devDependencies."}],"id":"create-the-project"},{"title":"Write the first two routes","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["Create server.js:",false]]]},{"k":"code","t":"const express = require(\"express\");\nconst app = express();\nconst PORT = 3001;\n\napp.get(\"/\", (req, res) => {\n  res.send(\"Hello from Express\");\n});\n\napp.get(\"/api/health\", (req, res) => {\n  res.json({ status: \"ok\" });\n});","lang":"javascript"},{"k":"code","t":"\napp.listen(PORT, () => console.log(`Running at http://localhost:${PORT}`));","lang":"javascript"},{"k":"callout","t":"Run npm run dev. You should see Running at http://localhost:3001. Open that address in the browser to see \"Hello from Express\", then open http://localhost:3001/api/health to see {\"status\":\"ok\"}."}],"id":"write-the-first-two-routes"},{"title":"Add the notices routes","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"list","items":[[["Put this between the health route and app.listen:",false]]]},{"k":"code","t":"const notices = [\n  { id: 1, title: \"Library hours extended\" },\n  { id: 2, title: \"Enrollment reminder\" },\n  { id: 3, title: \"Programming contest\" },\n];\n\napp.get(\"/api/notices\", (req, res) => {\n  res.json(notices);\n});\n\napp.get(\"/api/notices/:id\", (req, res) => {","lang":"javascript"},{"k":"code","t":"  const id = Number(req.params.id);\n  const notice = notices.find((n) => n.id === id);\n  if (!notice) {\n    return res.status(404).json({ error: \"Notice not found\" });\n  }\n  res.json(notice);\n});","lang":"javascript"},{"k":"callout","t":"Save (nodemon restarts the server). Check /api/notices (three notices), /api/notices/2 (one notice), and /api/notices/99 (a 404 with { \"error\": \"Notice not found\" }). The return before the 404 answer stops the function, so the route never answers twice."}],"id":"add-the-notices-routes"},{"title":"Add the search route","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"code","t":"app.get(\"/api/search\", (req, res) => {\n  const term = (req.query.term || \"\").toLowerCase();\n  res.json(notices.filter((n) => n.title.toLowerCase().includes(term)));\n});","lang":"javascript"},{"k":"callout","t":"Open /api/search?term=lib. You should see only the library notice. Open /api/search with no term and you should see all three."}],"id":"add-the-search-route"},{"title":"Write the logger middleware","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["Add it above every route, right after const PORT = 3001;:",false]]]},{"k":"code","t":"function logger(req, res, next) {\n  console.log(`${req.method} ${req.url}`);\n  next();\n}\napp.use(logger);","lang":"javascript"},{"k":"list","items":[[["Refresh a few pages.",false]]]},{"k":"list","items":[[["The terminal should print one line per request, such as GET /api/notices/2.",false]],[["Now try an experiment: cut the app.use(logger) line and paste it below the routes.",false]]]}],"extra":["The requests that a route answers stop appearing in the log, because the route answered before the logger got its turn. Put it back at the top. That is why order matters in Express."],"id":"write-the-logger-middleware"},{"title":"Serve your Week 1 page","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["Create a folder named public inside the project and copy your Week 1 index.html and styles.css into it.",false]],[["Add this line above the routes, below the logger:",false]]]},{"k":"code","t":"app.use(express.static(\"public\"));","lang":"javascript"},{"k":"list","items":[[["Open http://localhost:3001/index.html.",false]]]},{"k":"list","items":[[["You should see your styled Campus Notices page, and the Network tab shows both files loading with 200.",false]],[["(Your GET / route still answers the address /, because routes and middleware run from top to bottom and your route is not blocked by the static line.",false]]]}],"extra":["Try moving the GET / route below express.static and see which one answers / then.)"],"id":"serve-your-week-1-page"},{"title":"Add the 404 and error handlers at the bottom","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"list","items":[[["They must be the last things before app.listen:",false]]]},{"k":"code","t":"app.use((req, res) => {\n  res.status(404).json({ error: \"Route not found\" });\n});\n\n// error-handling middleware has FOUR parameters\napp.use((err, req, res, next) => {\n  console.error(err);\n  res.status(500).json({ error: \"Something went wrong\" });\n});","lang":"javascript"},{"k":"callout","t":"Open /nope. You should see { \"error\": \"Route not found\" }. To test the error handler, add this temporary route above the 404 handler, open /api/boom, confirm you get a 500 JSON answer, then delete the route:"},{"k":"code","t":"app.get(\"/api/boom\", () => {\n  throw new Error(\"test error\");\n});","lang":"javascript"}],"id":"add-the-404-and-error-handlers-at-the-bottom"},{"title":"Test everything in Postman","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"list","items":[[["Send each request below and compare the status code.",false]]]},{"k":"table","head":["Request","Expected"],"rows":[["GET /","200, text"],["GET /api/health","200, { \"status\": \"ok\" }"],["GET /api/notices","200, array of 3"],["GET /api/notices/2","200, one notice"],["GET /api/notices/99","404"],["GET /api/search?term=lib","200, one match"],["GET /nope","404, JSON error"]]},{"k":"list","items":[[["Show your instructor the passing table and the terminal log.",false]]]}],"id":"test-everything-in-postman"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["At least five routes work, plus the static page.",false]],[["The logger prints one line for every request.",false]],[["Unknown routes return a JSON 404, and the error handler is the last thing registered.",false]],[["You can explain, in one sentence, why the logger must come before the routes.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Write a middleware requireKey that checks for a header x-api-key equal to \"lab-secret\". Return 401 if it is missing or wrong. Apply it to only one route. (This is a first taste of Week 16.)"}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"slideCount":19,"pptx":"downloads/laboratory/Week_05_Laboratory_Express_routing_and_middleware.pptx"},{"week":6,"title":"REST design, status codes and validation","focus":"in-memory CRUD API, tested in Postman","duration":"3 hours","file":"Week_06_Laboratory_REST_design_status_codes_and_validation.pptx","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Build a complete CRUD API for notices and prove that it works with a Postman collection.",false]],[["Deliverable. ",true],["A project folder with the API and an exported Postman collection that contains at least ten requests with passing tests.",false]]]}],"extra":["Your collection must include these failure cases: an empty title, a missing body, an unknown id on GET, PUT and DELETE."],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: in-memory CRUD API with Postman","tag":null,"kind":"divider","sub":"Build the API first (Steps 1 to 4), then prove it works with Postman (Steps 5 to 7).","id":"step-by-step-guide-in-memory-crud-api-with-postm"},{"title":"Set up the project","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"code","t":"mkdir notices-api\ncd notices-api\nnpm init -y\nnpm install express cors\nnpm install --save-dev nodemon","lang":"bash"},{"k":"callout","t":"Set the dev script to nodemon server.js, and create .gitignore with the line node_modules/. You should see node_modules in the folder, ignored by Git."}],"id":"set-up-the-project"},{"title":"Write server.js: setup, GET and POST","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"code","t":"const express = require(\"express\");\nconst cors = require(\"cors\");\nconst app = express();\n\napp.use(cors());\napp.use(express.json());\n\nlet notices = [\n  { id: 1, title: \"Library hours extended\", message: \"Open until 9 PM.\", createdAt: \"2026-10-12T08:00:00.000Z\" },\n];\nlet nextId = 2;\n\nfunction validateNotice(body) {","lang":"javascript"},{"k":"code","t":"  const { title, message } = body || {};\n  if (typeof title !== \"string\" || title.trim() === \"\") return \"Title is required.\";\n  if (typeof message !== \"string\" || message.trim() === \"\") return \"Message is required.\";\n  if (title.trim().length > 100) return \"Title must be 100 characters or fewer.\";\n  return null; // null means valid\n}\n\napp.get(\"/api/notices\", (req, res) => {\n  res.json(notices);\n});","lang":"javascript"},{"k":"code","t":"app.get(\"/api/notices/:id\", (req, res) => {\n  const notice = notices.find((n) => n.id === Number(req.params.id));\n  if (!notice) return res.status(404).json({ error: \"Notice not found.\" });\n  res.json(notice);\n});\n\napp.post(\"/api/notices\", (req, res) => {\n  const problem = validateNotice(req.body);\n  if (problem) return res.status(400).json({ error: problem });\n  const notice = {\n    id: nextId++,\n    title: req.body.title.trim(),\n    message: req.body.message.trim(),","lang":"javascript"},{"k":"code","t":"    createdAt: new Date().toISOString(),\n  };\n  notices.push(notice);\n  res.status(201).json(notice);\n});\n\napp.listen(3001, () => console.log(\"API on http://localhost:3001\"));","lang":"javascript"},{"k":"callout","t":"Run npm run dev and test in Postman: GET /api/notices gives 200, a good POST gives 201, and a POST with { \"title\": \"\" } gives 400."}],"id":"write-server-js-setup-get-and-post"},{"title":"Add PUT and DELETE","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"list","items":[[["Put these above app.listen:",false]]]},{"k":"code","t":"app.put(\"/api/notices/:id\", (req, res) => {\n  const notice = notices.find((n) => n.id === Number(req.params.id));\n  if (!notice) return res.status(404).json({ error: \"Notice not found.\" });\n  const problem = validateNotice(req.body);\n  if (problem) return res.status(400).json({ error: problem });\n  notice.title = req.body.title.trim();\n  notice.message = req.body.message.trim();\n  res.json(notice);\n});","lang":"javascript"},{"k":"code","t":"app.delete(\"/api/notices/:id\", (req, res) => {\n  const index = notices.findIndex((n) => n.id === Number(req.params.id));\n  if (index === -1) return res.status(404).json({ error: \"Notice not found.\" });\n  notices.splice(index, 1);\n  res.status(204).send();\n});","lang":"javascript"},{"k":"callout","t":"Test: PUT /api/notices/1 with a new title gives 200; DELETE /api/notices/1 gives 204 with an empty body; the same DELETE again gives 404."}],"id":"add-put-and-delete"},{"title":"Add the optional search filter","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["Change the list route to:",false]]]},{"k":"code","t":"app.get(\"/api/notices\", (req, res) => {\n  const { search } = req.query;\n  if (search) {\n    return res.json(notices.filter((n) => n.title.toLowerCase().includes(search.toLowerCase())));\n  }\n  res.json(notices);\n});","lang":"javascript"},{"k":"callout","t":"Test GET /api/notices?search=lib. You should see only matching notices."}],"id":"add-the-optional-search-filter"},{"title":"Create the Postman collection","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["In Postman, click New, then Collection, and name it Notices API.",false]],[["Open the collection's Variables tab, add baseUrl with the value http://localhost:3001, and save.",false]],[["Add a request for every row in the table below. Use {{baseUrl}}/api/notices as the URL start. For requests with a body, choose Body, raw, JSON.",false]]]},{"k":"table","head":["#","Request","Expected status"],"rows":[["1","GET {{baseUrl}}/api/notices","200"],["2","GET {{baseUrl}}/api/notices/1","200"],["3","GET {{baseUrl}}/api/notices/999","404"],["4","POST with a valid title and message","201"],["5","POST with an empty title","400"],["6","POST with no body","400"],["7","PUT /api/notices/1 with valid data","200"],["8","PUT /api/notices/999 with valid data","404"],["9","PUT /api/notices/1 with an empty title","400"],["10","DELETE /api/notices/999","404"],["11","DELETE an existing notice","204"],["12","GET /api/notices?search=lib","200"]]},{"k":"list","items":[[["Send each one and check the status.",false]],[["Restart the server (Ctrl+C, then npm run dev) whenever your data changes so the requests start from a known state.",false]]]}],"id":"create-the-postman-collection"},{"title":"Add tests to at least five requests","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["Open a request, choose the Scripts tab (called Tests in older versions), and paste a check.",false]],[["Examples:",false]]]},{"k":"code","t":"pm.test(\"Status is 201\", () => pm.response.to.have.status(201));\n\npm.test(\"Response has a numeric id\", () => {\n  pm.expect(pm.response.json().id).to.be.a(\"number\");\n});\n\npm.test(\"Error message is a string\", () => {","lang":"javascript"},{"k":"code","t":"  pm.expect(pm.response.json().error).to.be.a(\"string\");\n});","lang":"javascript"},{"k":"callout","t":"Send the request again. In the Test Results panel you should see a green PASS for each check. Add checks for status codes on the failure cases too."}],"id":"add-tests-to-at-least-five-requests"},{"title":"Export and show your instructor","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"list","items":[[["Right-click the collection, choose Export, pick the Collection v2.1 format, and save the JSON file in your project folder.",false]],[["Your collection must include these failure cases: an empty title, a missing body, and an unknown id on GET, PUT and DELETE.",false]]]}],"id":"export-and-show-your-instructor"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["All five routes work and return the right status codes (200, 201, 204, 400, 404).",false]],[["The collection has at least ten requests and at least five have passing pm.test checks.",false]],[["The exported JSON file is in your project folder.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Add PATCH /api/notices/:id that updates only the fields the client sends. Decide how validation should behave when only one field is present, and write two Postman tests that prove it."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"slideCount":19,"pptx":"downloads/laboratory/Week_06_Laboratory_REST_design_status_codes_and_validation.pptx"},{"week":7,"title":"MongoDB and Mongoose basics","focus":"connect the API to a database","duration":"3 hours","file":"Week_07_Laboratory_MongoDB_and_Mongoose_basics.pptx","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Move your Week 6 notices out of the array and into MongoDB, starting with reading data.",false]],[["Deliverable. ",true],["A running API whose GET /api/notices returns notices stored in MongoDB, a seed.js script, and a screenshot of your documents in Atlas or MongoDB Compass.",false]]]}],"extra":["If your first connection fails, read the first line of the error. It usually says whether the problem is the password, the allowed IP address, or a typo in the string."],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: connect the API to MongoDB","tag":null,"kind":"divider","sub":"Follow the steps in order.","id":"step-by-step-guide-connect-the-api-to-mongodb"},{"title":"Get a database","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"list","items":[[["Choose one:",false]],[["MongoDB Atlas (free). Create an account, create a free cluster, add a database user (note the username and password), and under Network Access allow your IP address. Click Connect, choose Drivers, and copy the connection string. Replace <password> with your real password, and add the database name before the ?, for example ...mongodb.net/campus-notices?retryWrites=true.",false]],[["Local MongoDB. Install it, start the server, and use mongodb://127.0.0.1:27017/campus-notices.",false]]]},{"k":"list","items":[[["You should have one connection string saved in a text file for now.",false]],[["If the school network blocks Atlas, use the local install.",false]]]}],"id":"get-a-database"},{"title":"Prepare the project","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["Copy your Week 6 folder to a new folder named notices-api-mongo.",false]],[["In it, run:",false]]]},{"k":"code","t":"npm install mongoose dotenv","lang":"bash"},{"k":"callout","t":"Create a .env file with your string, and add .env to .gitignore:"},{"k":"code","t":"# .env\nMONGODB_URI=mongodb://127.0.0.1:27017/campus-notices","lang":"javascript"},{"k":"code","t":"# .gitignore\nnode_modules/\n.env","lang":"text"}],"id":"prepare-the-project"},{"title":"Write db.js and connect","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"list","items":[[["Create db.js:",false]]]},{"k":"code","t":"require(\"dotenv\").config();\nconst mongoose = require(\"mongoose\");\n\nasync function connectDB() {\n  try {\n    await mongoose.connect(process.env.MONGODB_URI);\n    console.log(\"MongoDB connected\");\n  } catch (err) {\n    console.error(\"MongoDB connection failed:\", err.message);\n    process.exit(1);\n  }","lang":"javascript"},{"k":"code","t":"}\n\nmodule.exports = connectDB;","lang":"javascript"},{"k":"callout","t":"At the top of server.js, add const connectDB = require(\"./db\");. At the bottom, replace the app.listen(...) line with:"},{"k":"code","t":"connectDB().then(() => {\n  app.listen(3001, () => console.log(\"API on http://localhost:3001\"));\n});","lang":"javascript"},{"k":"callout","t":"Run npm run dev. You should see MongoDB connected and then API on http://localhost:3001. If you see an error, read its first line:"},{"k":"table","head":["First line says","Likely cause"],"rows":[["bad auth or Authentication failed","Wrong username or password in the string"],["ENOTFOUND or timed out","Typo in the host name, or your IP address is not allowed in Atlas"],["ECONNREFUSED 127.0.0.1","The local MongoDB server is not running"],["MONGODB_URI is undefined","The .env file is missing, misnamed, or in the wrong folder"]]}],"id":"write-db-js-and-connect"},{"title":"Write the model","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["Create models/Notice.js:",false]]]},{"k":"code","t":"const mongoose = require(\"mongoose\");\n\nconst noticeSchema = new mongoose.Schema(\n  {\n    title: { type: String, required: true, trim: true, maxlength: 100 },\n    message: { type: String, required: true, trim: true, maxlength: 500 },\n  },\n  { timestamps: true } // adds createdAt and updatedAt automatically\n);\n\nmodule.exports = mongoose.model(\"Notice\", noticeSchema);","lang":"javascript"}],"id":"write-the-model"},{"title":"Write and run seed.js","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["This script puts starter data in the database so you do not type it by hand:",false]]]},{"k":"code","t":"const mongoose = require(\"mongoose\");\nconst connectDB = require(\"./db\");\nconst Notice = require(\"./models/Notice\");\n\nasync function seed() {\n  await connectDB();\n  await Notice.deleteMany({});\n  await Notice.insertMany([","lang":"javascript"},{"k":"code","t":"    { title: \"Library hours extended\", message: \"Open until 9 PM during midterm week.\" },\n    { title: \"Enrollment reminder\", message: \"Last day to add or drop subjects is Friday.\" },\n    { title: \"Programming contest\", message: \"Sign up at the CCS office by Monday.\" },\n  ]);\n  console.log(\"Seeded 3 notices\");\n  await mongoose.disconnect();\n}\n\nseed();","lang":"javascript"},{"k":"callout","t":"Run node seed.js. You should see Seeded 3 notices. Open Atlas (Browse Collections) or MongoDB Compass and find the notices collection with three documents. Take your screenshot now."}],"id":"write-and-run-seed-js"},{"title":"Read from the database","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["In server.js, add const Notice = require(\"./models/Notice\"); and replace the two GET routes:",false]]]},{"k":"code","t":"app.get(\"/api/notices\", async (req, res) => {\n  const notices = await Notice.find().sort({ createdAt: -1 });\n  res.json(notices);\n});\n\napp.get(\"/api/notices/:id\", async (req, res) => {\n  try {\n    const notice = await Notice.findById(req.params.id);","lang":"javascript"},{"k":"code","t":"    if (!notice) return res.status(404).json({ error: \"Notice not found.\" });\n    res.json(notice);\n  } catch (err) {\n    if (err.name === \"CastError\") return res.status(400).json({ error: \"Invalid id.\" });\n    res.status(500).json({ error: \"Something went wrong.\" });\n  }\n});","lang":"javascript"},{"k":"callout","t":"In Postman, GET /api/notices should return three notices. Look at one: its identifier is _id, a long string, not id. Copy one _id and GET /api/notices/<that id> to see a single notice. Try GET /api/notices/abc and confirm a 400."}],"id":"read-from-the-database"},{"title":"Prove the data is persistent","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"list","items":[[["Stop the server (Ctrl+C), start it again, and GET /api/notices.",false]],[["The three notices are still there.",false]],[["Compare that with Week 6, where a restart emptied the array.",false]]]}],"id":"prove-the-data-is-persistent"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["You see MongoDB connected each time the server starts.",false]],[["GET /api/notices and GET /api/notices/:id read from MongoDB.",false]],[["seed.js works, .env is in .gitignore, and you have the screenshot of your documents.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Add a category field to the schema that accepts only \"general\", \"academic\" or \"event\" and defaults to \"general\". Let GET /api/notices?category=event filter the results."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"slideCount":19,"pptx":"downloads/laboratory/Week_07_Laboratory_MongoDB_and_Mongoose_basics.pptx"},{"week":8,"title":"Mongoose CRUD, error handling and review","focus":"persistent API","duration":"3 hours","file":"Week_08_Laboratory_Mongoose_CRUD_error_handling_and_review.pptx","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Rebuild your Week 6 API on top of MongoDB with a clean, layered structure.",false]],[["Deliverable. ",true],["A server with routes, controllers, a model and an error handler. Every route works, data survives a restart, and your Postman collection from Week 6 passes with only small changes.",false]]]}],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: persistent API","tag":null,"kind":"divider","sub":"You are rebuilding the same API in a cleaner structure.","id":"step-by-step-guide-persistent-api"},{"title":"Create the folder structure","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"list","items":[[["In your Week 7 project, run:",false]]]},{"k":"code","t":"mkdir controllers routes middleware","lang":"bash"},{"k":"callout","t":"You should end up with this layout (move Notice.js and db.js if they are not already there):"},{"k":"code","t":"server/\n  app.js\n  server.js\n  db.js\n  models/Notice.js\n  controllers/noticeController.js\n  routes/notices.js\n  middleware/asyncHandler.js\n  middleware/errorHandler.js","lang":"javascript"}],"id":"create-the-folder-structure"},{"title":"Write app.js and server.js","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["app.js builds the Express app and does not start listening. server.js connects to the database, then listens.",false]]]},{"k":"code","t":"// app.js\nconst express = require(\"express\");\nconst cors = require(\"cors\");\nconst noticeRoutes = require(\"./routes/notices\");\nconst errorHandler = require(\"./middleware/errorHandler\");\n\nconst app = express();\napp.use(cors());\napp.use(express.json());","lang":"javascript"},{"k":"code","t":"app.use(\"/api/notices\", noticeRoutes);\napp.use((req, res) => res.status(404).json({ error: \"Route not found.\" }));\napp.use(errorHandler); // registered LAST\n\nmodule.exports = app;","lang":"javascript"},{"k":"code","t":"// server.js\nrequire(\"dotenv\").config();\nconst app = require(\"./app\");\nconst connectDB = require(\"./db\");\n\nconst PORT = process.env.PORT || 3001;","lang":"javascript"},{"k":"code","t":"\nconnectDB().then(() => {\n  app.listen(PORT, () => console.log(`API on http://localhost:${PORT}`));\n});","lang":"javascript"}],"id":"write-app-js-and-server-js"},{"title":"Write the controller and the router","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"code","t":"// controllers/noticeController.js\nconst Notice = require(\"../models/Notice\");\nconst asyncHandler = require(\"../middleware/asyncHandler\");\n\nexports.getNotices = asyncHandler(async (req, res) => {\n  const notices = await Notice.find().sort({ createdAt: -1 });\n  res.json(notices);\n});\n\nexports.getNotice = asyncHandler(async (req, res) => {\n  const notice = await Notice.findById(req.params.id);\n  if (!notice) return res.status(404).json({ error: \"Notice not found.\" });\n  res.json(notice);","lang":"javascript"},{"k":"code","t":"});\n\nexports.createNotice = asyncHandler(async (req, res) => {\n  const { title, message } = req.body;\n  const notice = await Notice.create({ title, message });\n  res.status(201).json(notice);\n});\n\nexports.updateNotice = asyncHandler(async (req, res) => {\n  const { title, message } = req.body;\n  const notice = await Notice.findByIdAndUpdate(\n    req.params.id,\n    { title, message },\n    { new: true, runValidators: true }","lang":"javascript"},{"k":"code","t":"  );\n  if (!notice) return res.status(404).json({ error: \"Notice not found.\" });\n  res.json(notice);\n});\n\nexports.deleteNotice = asyncHandler(async (req, res) => {\n  const notice = await Notice.findByIdAndDelete(req.params.id);\n  if (!notice) return res.status(404).json({ error: \"Notice not found.\" });\n  res.status(204).send();\n});","lang":"javascript"},{"k":"code","t":"// routes/notices.js\nconst express = require(\"express\");\nconst c = require(\"../controllers/noticeController\");\n\nconst router = express.Router();\nrouter.get(\"/\", c.getNotices);\nrouter.get(\"/:id\", c.getNotice);\nrouter.post(\"/\", c.createNotice);\nrouter.put(\"/:id\", c.updateNotice);\nrouter.delete(\"/:id\", c.deleteNotice);\n\nmodule.exports = router;","lang":"javascript"}],"id":"write-the-controller-and-the-router"},{"title":"Write the two middleware files","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"code","t":"// middleware/asyncHandler.js\nmodule.exports = (fn) => (req, res, next) =>\n  Promise.resolve(fn(req, res, next)).catch(next);","lang":"javascript"},{"k":"code","t":"// middleware/errorHandler.js\nmodule.exports = (err, req, res, next) => {\n  if (err.name === \"ValidationError\") {\n    const message = Object.values(err.errors).map((e) => e.message).join(\" \");\n    return res.status(400).json({ error: message });\n  }\n  if (err.name === \"CastError\") {\n    return res.status(400).json({ error: \"Invalid id.\" });","lang":"javascript"},{"k":"code","t":"  }\n  console.error(err); // the real error stays on the server\n  res.status(500).json({ error: \"Something went wrong.\" });\n};","lang":"javascript"},{"k":"callout","t":"Run npm run dev. You should see MongoDB connected and API on http://localhost:3001. GET /api/notices should return your seeded notices."}],"id":"write-the-two-middleware-files"},{"title":"Run your Week 6 collection","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["Open your Postman collection and run every request.",false]],[["Some will fail.",false]]]}],"extra":["The usual reasons: ids in the URLs are numbers (1) but MongoDB ids are long strings, so replace them with a real _id copied from GET /api/notices; and a test that checks for a numeric id should now check for _id. Fix the requests until all pass."],"id":"run-your-week-6-collection"},{"title":"Test the bad cases on purpose","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"table","head":["Request","Expected result"],"rows":[["POST with an empty title","400 and a message from the schema"],["GET /api/notices/abc","400 and Invalid id."],["GET /api/notices/507f1f77bcf86cd799439011 (valid-looking, but no such notice)","404 and Notice not found."],["DELETE the same id twice","204, then 404"]]},{"k":"list","items":[[["If the invalid-id request hangs or crashes, check that you wrapped every controller in asyncHandler and that errorHandler is registered last.",false]]]}],"id":"test-the-bad-cases-on-purpose"},{"title":"Prove it persists","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"list","items":[[["Stop and restart the server, then GET /api/notices.",false]],[["The data should be there.",false]]]}],"id":"prove-it-persists"},{"title":"Complete the review checklist","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"list","items":[[["Go back to the Weeks 1 to 8 review table in the lecture.",false]],[["Mark each row honestly as \"I can do this\" or \"I need to revisit this\".",false]],[["Bring your list to the midterm preparation.",false]]]}],"id":"complete-the-review-checklist"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["The server follows the folder layout above, and errorHandler is registered last.",false]],[["Every route works, and the bad-case table gives the expected codes.",false]],[["Your Week 6 collection passes with only small changes.",false]],[["Data survives a restart, and your checklist is complete.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Add pagination: GET /api/notices?page=2&limit=5 returns the second page of five notices, and the response includes the total count so a client can build page links."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"slideCount":20,"pptx":"downloads/laboratory/Week_08_Laboratory_Mongoose_CRUD_error_handling_and_review.pptx"},{"week":9,"title":"Midterm","focus":"midterm practical","duration":"3 hours","file":"Week_09_Laboratory_Midterm.pptx","sections":[{"title":"The midterm practical","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["An individual practical exam on Weeks 1 to 8: web basics, JavaScript, Node.js, Express, REST and MongoDB with Mongoose.",false]],[["Your instructor gives you the task at the start of the session. You have 3 hours.",false]],[["The task is new, but every skill it needs comes from the Week 1 to 8 labs.",false]]]}],"id":"the-midterm-practical"},{"title":"Rules for the exam","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["You may use your own old code and the module.",false]],[["You may not use the internet or messaging apps.",false]],[["Work alone. Ask your instructor only about the computer, not the solution.",false]]]}],"id":"rules-for-the-exam"},{"title":"How to prepare","tag":"PREPARE","kind":"prepare","blocks":[{"k":"list","items":[[["Make sure your Week 3, 5, 6, 7 and 8 lab deliverables run.",false]],[["Practise building an Express and Mongoose API from an empty folder without copying and pasting.",false]],[["Practise testing every route in Postman, with a success case and a failure case.",false]]]}],"id":"how-to-prepare"},{"title":"On the day: plan first","tag":"EXAM DAY","kind":"examday","blocks":[{"k":"list","items":[[["Read the requirements twice, then plan on paper: the routes, the fields, and the status code for each case.",false]],[["Set up the project: npm init -y; install express, cors, mongoose, dotenv and nodemon.",false]],[["Add .gitignore with node_modules/ and .env before your first commit.",false]]]}],"id":"on-the-day-plan-first"},{"title":"On the day: build and test","tag":"EXAM DAY","kind":"examday","blocks":[{"k":"list","items":[[["Build one route at a time and test it in Postman before you write the next one.",false]],[["Build a Postman collection with success and failure cases, and save it with your project.",false]],[["Review before you submit: right methods, paths and status codes; validation errors return the error JSON; unknown and invalid ids are handled.",false]]]}],"id":"on-the-day-build-and-test"},{"title":"Time budget (suggested)","tag":"EXAM DAY","kind":"examday","blocks":[{"k":"table","head":["Stage","Minutes"],"rows":[["Read and plan","10"],["Set up the project","20"],["Model and structure","25"],["Build routes, one at a time","45"],["Query filter","20"],["Postman collection","30"],["Final review","15"]]},{"k":"callout","t":"If you run out of time, a working version with fewer routes earns more than an unfinished version of all of them."}],"id":"time-budget-suggested"},{"title":"Catch-up option","tag":"CATCH-UP","kind":"catchup","blocks":[{"k":"list","items":[[["A midterm week is also a good time to catch up if you have fallen behind.",false]],[["If your instructor has marked you for catch-up, finish these deliverables in order and show each one as you finish it.",false]]]},{"k":"table","head":["Order","Deliverable","From"],"rows":[["1","A page that fetches and displays data from a public API","Week 3"],["2","An Express server with at least four routes and a logger","Week 5"],["3","An in-memory CRUD API with validation and a Postman collection","Week 6"],["4","The same API connected to MongoDB","Weeks 7 and 8"]]}],"id":"catch-up-option"}],"quiz":[],"refs":[],"refsIntro":null,"slideCount":8,"pptx":"downloads/laboratory/Week_09_Laboratory_Midterm.pptx"},{"week":10,"title":"Install PostgreSQL; notices database","focus":"build the notices and categories tables","duration":"3 hours","file":null,"sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Install PostgreSQL, build the notices and categories tables for the Campus Notices Board, and write CRUD and join queries against sample data.",false]],[["Deliverable. ",true],["Lab 10 output: a notices_db database and a file queries.sql with your CRUD and join queries, plus a screenshot of \\d notices and one join result.",false]]]}],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: the notices database","tag":null,"kind":"divider","sub":"Run each statement in psql or in pgAdmin's Query Tool, and check the result before moving on.","id":"step-by-step-guide-the-notices-database"},{"title":"Install PostgreSQL and open psql","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"list","items":[[["Install PostgreSQL 14 or newer from postgresql.org. Keep psql and pgAdmin ticked, and write down the password for the postgres user.",false]]]},{"k":"code","t":"psql --version\npsql -U postgres","lang":"bash"},{"k":"callout","t":"A prompt ending in =# means you are connected. If psql is not found, add the PostgreSQL bin folder to your PATH or open SQL Shell (psql) from the Start menu. You may also use pgAdmin for every step."}],"id":"install-postgresql-and-open-psql"},{"title":"Create the database","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"code","t":"CREATE DATABASE notices_db;\n\\c notices_db","lang":"sql"},{"k":"callout","t":"The prompt should now read notices_db=#. Run \\dt; it should say no relations found."}],"id":"create-the-database"},{"title":"Create the categories table","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"code","t":"CREATE TABLE categories (\n  id SERIAL PRIMARY KEY,\n  name VARCHAR(30) NOT NULL UNIQUE\n);","lang":"sql"},{"k":"list","items":[[["Try to break it later: inserting the same name twice should fail.",false]]]}],"id":"create-the-categories-table"},{"title":"Create the notices table","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"code","t":"CREATE TABLE notices (\n  id SERIAL PRIMARY KEY,\n  title VARCHAR(120) NOT NULL,\n  message TEXT NOT NULL,\n  category_id INTEGER REFERENCES categories(id),\n  pinned BOOLEAN NOT NULL DEFAULT false,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  CHECK (length(trim(title)) > 0)\n);","lang":"sql"},{"k":"list","items":[[["Run \\d notices and take your first screenshot. You should see the foreign key and the CHECK rule listed.",false]]]}],"id":"create-the-notices-table"},{"title":"Insert sample data","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"code","t":"INSERT INTO categories (name) VALUES ('academic'), ('events'), ('urgent');\n\nINSERT INTO notices (title, message, category_id, pinned) VALUES\n  ('Library hours extended', 'Open until 9 PM.', 1, false),\n  ('Foundation Day program', 'Gym, 8 AM.', 2, true),\n  ('Enrollment deadline', 'Submit forms by Friday.', 3, true),\n  ('Lost umbrella', 'Found near Room 102.', NULL, false);","lang":"sql"},{"k":"callout","t":"The last notice has no category on purpose. You will need it in Step 8."}],"id":"insert-sample-data"},{"title":"Read with SELECT, WHERE and ORDER BY","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"code","t":"SELECT * FROM notices;\nSELECT id, title FROM notices WHERE pinned = true ORDER BY created_at DESC;\nSELECT title FROM notices WHERE title ILIKE '%library%';","lang":"sql"},{"k":"list","items":[[["Write one more query of your own: the three newest notices, using ORDER BY and LIMIT 3.",false]]]}],"id":"read-with-select-where-and-order-by"},{"title":"Update and delete, then break a rule","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"code","t":"UPDATE notices SET pinned = false WHERE title = 'Foundation Day program';\nDELETE FROM notices WHERE title = 'Lost umbrella';\n\n-- These two should fail. Read each error message.\nINSERT INTO categories (name) VALUES ('urgent');\nINSERT INTO notices (title, message, category_id) VALUES ('Bad', 'No such category', 99);","lang":"sql"},{"k":"list","items":[[["Which constraint rejected each statement? Write the answer next to the query in queries.sql as a comment.",false]]]},{"k":"callout","t":"Put the Lost umbrella notice back with its INSERT before Step 8."}],"id":"update-and-delete-then-break-a-rule"},{"title":"Join notices to categories","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"code","t":"SELECT n.title, c.name AS category\nFROM notices n\nJOIN categories c ON c.id = n.category_id;\n\nSELECT n.title, c.name AS category\nFROM notices n\nLEFT JOIN categories c ON c.id = n.category_id;","lang":"sql"},{"k":"list","items":[[["Compare the two results. Which notice appears only in the second, and why? Take a screenshot of the second result.",false]]]}],"id":"join-notices-to-categories"},{"title":"Count notices per category","tag":"STEP 9","kind":"step","step":9,"blocks":[{"k":"code","t":"SELECT c.name, COUNT(n.id) AS total\nFROM categories c\nLEFT JOIN notices n ON n.category_id = c.id\nGROUP BY c.name\nORDER BY total DESC;","lang":"sql"}],"id":"count-notices-per-category"},{"title":"Save your queries","tag":"STEP 10","kind":"step","step":10,"blocks":[{"k":"list","items":[[["Copy every working statement into a file named queries.sql, in the order you ran them, with a short comment above each.",false]],[["Re-run the whole file on a fresh database to prove it works: DROP DATABASE notices_db; then repeat from Step 2 using only your file.",false]]]}],"id":"save-your-queries"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["PostgreSQL is installed and you can connect with psql or pgAdmin.",false]],[["The categories and notices tables exist, and \\d notices shows the foreign key.",false]],[["You have inserted, selected, updated and deleted rows, and seen two constraint errors.",false]],[["Your queries.sql contains the CRUD, join and count queries and runs from top to bottom.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Write a query that lists the categories that have no notices at all. Hint: start from categories, LEFT JOIN notices, and keep the rows where the notice id IS NULL."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"slideCount":null,"pptx":null},{"week":11,"title":"Your API on PostgreSQL","focus":"move the notices API from MongoDB to PostgreSQL","duration":"3 hours","file":null,"sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Move your Week 8 notices API from MongoDB to PostgreSQL using raw SQL with pg, and prove every route still behaves the same.",false]],[["Deliverable. ",true],["Lab 11 output: the notices API running on PostgreSQL (Project Checkpoint 3), with your Postman collection passing.",false]]]}],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: move the API to PostgreSQL","tag":null,"kind":"divider","sub":"Work in a copy of your Week 8 project so the MongoDB version stays safe.","id":"step-by-step-guide-move-the-api-to-postgresql"},{"title":"Copy the project and install pg","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"code","t":"cp -r notices-api notices-api-pg\ncd notices-api-pg\nnpm install pg dotenv","lang":"bash"},{"k":"callout","t":"On Windows without cp, copy the folder in File Explorer. Make sure the notices_db database and tables from Week 10 still exist."}],"id":"copy-the-project-and-install-pg"},{"title":"Add the connection file","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"code","t":"# .env\nDATABASE_URL=postgres://postgres:YOUR_PASSWORD@localhost:5432/notices_db","lang":"text"},{"k":"code","t":"// db.js\nrequire(\"dotenv\").config();\nconst { Pool } = require(\"pg\");\nconst pool = new Pool({ connectionString: process.env.DATABASE_URL });\nmodule.exports = { query: (text, params) => pool.query(text, params) };","lang":"javascript"},{"k":"code","t":"// temporary check, run with: node check.js\nconst db = require(\"./db\");\ndb.query(\"SELECT now()\").then((r) => { console.log(r.rows[0]); process.exit(); });","lang":"javascript"},{"k":"callout","t":"You should see the current time. If you see a password error, fix .env. Add .env to .gitignore."}],"id":"add-the-connection-file"},{"title":"List all notices","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"code","t":"exports.getAll = asyncHandler(async (req, res) => {\n  const { rows } = await db.query(\"SELECT * FROM notices ORDER BY created_at DESC\");\n  res.json(rows);\n});","lang":"javascript"},{"k":"list","items":[[["Test GET /api/notices in Postman. You should get the rows you inserted in Week 10.",false]]]}],"id":"list-all-notices"},{"title":"Get one notice","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"code","t":"exports.getOne = asyncHandler(async (req, res) => {\n  const { rows } = await db.query(\"SELECT * FROM notices WHERE id = $1\", [req.params.id]);\n  if (rows.length === 0) return res.status(404).json({ error: \"Notice not found.\" });\n  res.json(rows[0]);\n});","lang":"javascript"}],"id":"get-one-notice"},{"title":"Create a notice","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"code","t":"exports.create = asyncHandler(async (req, res) => {\n  const { title, message, category_id } = req.body;\n  const { rows } = await db.query(\n    \"INSERT INTO notices (title, message, category_id) VALUES ($1, $2, $3) RETURNING *\",\n    [title, message, category_id || null]\n  );\n  res.status(201).json(rows[0]);\n});","lang":"javascript"},{"k":"list","items":[[["Keep your validation middleware from Week 6. Test a good request (201) and one with no title (400).",false]]]}],"id":"create-a-notice"},{"title":"Update and delete","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"code","t":"exports.update = asyncHandler(async (req, res) => {\n  const { title, message, pinned } = req.body;\n  const { rows } = await db.query(\n    \"UPDATE notices SET title = $1, message = $2, pinned = $3 WHERE id = $4 RETURNING *\",\n    [title, message, pinned, req.params.id]\n  );\n  if (rows.length === 0) return res.status(404).json({ error: \"Notice not found.\" });\n  res.json(rows[0]);\n});\n\nexports.remove = asyncHandler(async (req, res) => {\n  const result = await db.query(\"DELETE FROM notices WHERE id = $1\", [req.params.id]);\n  if (result.rowCount === 0) return res.status(404).json({ error: \"Notice not found.\" });\n  res.status(204).end();\n});","lang":"javascript"}],"id":"update-and-delete"},{"title":"Teach the error handler the PostgreSQL codes","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"list","items":[[["Add the codes from the table below to your central errorHandler, then request GET /api/notices/abc and expect a 400, not a 500.",false]]]}],"id":"teach-the-error-handler-the-postgresql-codes"},{"title":"Run your Postman collection and compare","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"list","items":[[["Run the Week 6 collection against the new server.",false]],[["For every request, compare the status code with the Mongoose version. Write down any difference and the reason for it.",false]]]},{"k":"callout","t":"Typical differences: ids are numbers instead of ObjectIds, and the date field is now created_at."}],"id":"run-your-postman-collection-and-compare"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["No route uses Mongoose any more, and every query uses placeholders ($1, $2).",false]],[["All five routes work, and the bad-case requests return 400 or 404 instead of 500.",false]],[["Your Postman collection passes with only small changes.",false]],[["Data survives a server restart, and .env is not committed.",false]]]}],"id":"you-are-done-when"},{"title":"Why placeholders matter","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["Imagine a careless controller that glues the user's text into the SQL:",false]]]},{"k":"code","t":"// NEVER do this\nconst { search } = req.query;\nconst sql = \"SELECT * FROM notices WHERE title ILIKE '%\" + search + \"%'\";\nawait db.query(sql);","lang":"javascript"},{"k":"callout","t":"A normal visitor sends ?search=library and the SQL becomes ... ILIKE '%library%', which is fine. An attacker sends ?search=x%'; DELETE FROM notices; -- and the SQL text becomes:"},{"k":"code","t":"SELECT * FROM notices WHERE title ILIKE '%x%'; DELETE FROM notices; --%'","lang":"text"},{"k":"callout","t":"The database now sees a second statement and deletes every notice. This attack is called SQL injection. With a placeholder the values travel separately, so the same input is treated only as text to search for:"},{"k":"code","t":"await db.query(\"SELECT * FROM notices WHERE title ILIKE $1\", [`%${search}%`]);\n// searches for the literal text  x%'; DELETE FROM notices; --   and finds nothing","lang":"javascript"},{"k":"callout","t":"And this is what db.query hands back, so you know why the controllers read rows:"},{"k":"code","t":"const result = await db.query(\"SELECT id, title FROM notices WHERE id = $1\", [2]);\nconsole.log(result.rows);      // [ { id: 2, title: 'Enrollment reminder' } ]\nconsole.log(result.rowCount);  // 1\n// for an id that does not exist: rows is [] and rowCount is 0, so answer 404","lang":"javascript"},{"k":"callout","t":"PostgreSQL reports its own errors with a short code. Teach your central error handler the ones below, and the same safety net you built in Week 8 keeps working."},{"k":"table","head":["Code","Meaning","Reply"],"rows":[["22P02","Bad value for the type, such as the id abc","400"],["23502","A NOT NULL column was left empty","400"],["23514","A CHECK rule failed","400"],["23505","A UNIQUE rule failed, such as a duplicate email","409"]]}],"id":"why-placeholders-matter"},{"title":"A database error becoming the right answer","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["A client sends GET /api/notices/abc.",false]],[["The table's id column is a number, so PostgreSQL refuses to compare it with the text abc.",false]]]},{"k":"table","head":["Step","What happens"],"rows":[["1","The controller runs SELECT ... WHERE id = $1 with the value \"abc\""],["2","PostgreSQL throws an error with err.code === \"22P02\" (invalid text representation)"],["3","asyncHandler catches it and calls next(err)"],["4","The error handler sees code 22P02 in the table above and answers 400 { \"error\": \"Invalid id.\" }"]]},{"k":"list","items":[[["Now compare a registration with an email that already exists: the UNIQUE rule makes PostgreSQL throw 23505, and the same handler answers 409.",false]],[["The controllers never need a special try/catch; the database reports, asyncHandler forwards, and one handler decides the status code.",false]]]}],"extra":["A code that is not in your table falls through to the final 500 Something went wrong, and the real error is printed in the server terminal."],"id":"a-database-error-becoming-the-right-answer"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Add a search route: GET /api/notices?search=library. Use ILIKE with a placeholder, and test it with the SQL injection text from the worked example to prove it is safe."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"slideCount":null,"pptx":null},{"week":12,"title":"Static components; static notices page","focus":"build static components","duration":"3 hours","file":"Week_12_Laboratory_React_components_and_props.pptx","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Build the notice interface from components, using hard-coded data. There is no server in this lab, so you can focus on structure and props.",false]],[["Deliverable. ",true],["A React project with at least five components (Header, NoticeCard, NoticeList, EmptyState, Footer), a list rendered with map and keys, and a screenshot.",false]]]}],"extra":["Browser tip: if the page goes blank, open the Console. The error message usually names the file and line."],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: static React components","tag":null,"kind":"divider","sub":"Follow the steps in order and check the page in the browser after every step.","id":"step-by-step-guide-static-react-components"},{"title":"Create the project","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"code","t":"npm create vite@latest notices-ui -- --template react\ncd notices-ui\nnpm install\nnpm run dev","lang":"bash"},{"k":"callout","t":"Open the address Vite prints (usually http://localhost:5173). You should see the Vite and React starter page. Now open src/App.jsx, delete everything inside it and write only this, then delete src/App.css contents and the logo imports:"},{"k":"code","t":"export default function App() {\n  return <h1>Campus Notices</h1>;\n}","lang":"javascript"},{"k":"callout","t":"The page should now show only the heading. If it is blank, open the Console and read the first red line."}],"id":"create-the-project"},{"title":"Write Header and Footer","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["Create a folder src/components, then two files:",false]]]},{"k":"code","t":"// src/components/Header.jsx\nexport default function Header() {\n  return (\n    <header>\n      <h1>Campus Notices Board</h1>\n      <p>Announcements for every student</p>\n    </header>\n  );\n}","lang":"javascript"},{"k":"code","t":"// src/components/Footer.jsx\nexport default function Footer() {\n  return <footer>DMMMSU Campus Notices, 2026</footer>;\n}","lang":"javascript"},{"k":"callout","t":"Use them in App.jsx:"},{"k":"code","t":"import Header from \"./components/Header\";\nimport Footer from \"./components/Footer\";\n\nexport default function App() {\n  return (","lang":"javascript"},{"k":"code","t":"    <>\n      <Header />\n      <main>Notices will go here</main>\n      <Footer />\n    </>\n  );\n}","lang":"xml"},{"k":"callout","t":"You should see the header, the placeholder text and the footer in that order. Component names must start with a capital letter, or React treats them as HTML tags."}],"id":"write-header-and-footer"},{"title":"Write NoticeCard with props","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"code","t":"// src/components/NoticeCard.jsx\nexport default function NoticeCard({ title, message, createdAt, pinned }) {\n  return (\n    <article className=\"notice\">\n      <h2>{pinned && \"📌 \"}{title}</h2>\n      <p>{message}</p>\n      <small>{new Date(createdAt).toLocaleDateString()}</small>\n    </article>\n  );\n}","lang":"javascript"},{"k":"callout","t":"Test it by temporarily putting one card in App.jsx: <NoticeCard title=\"Library hours\" message=\"Open until 9 PM\" createdAt=\"2026-10-12\" pinned={true} />. You should see one card with the pin. Change pinned to {false} and the pin disappears. Props flow one way, down from the parent."}],"id":"write-noticecard-with-props"},{"title":"Write NoticeList and EmptyState","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["First the data, at the top of App.jsx (outside the component):",false]]]},{"k":"code","t":"const notices = [\n  { id: 1, title: \"Library hours extended\", message: \"Open until 9 PM.\", createdAt: \"2026-10-12\", pinned: true, category: \"academic\" },\n  { id: 2, title: \"Programming contest\", message: \"Sign up at the CCS office.\", createdAt: \"2026-10-13\", pinned: false, category: \"events\" },\n  { id: 3, title: \"Enrollment reminder\", message: \"Last day to add or drop is Friday.\", createdAt: \"2026-10-14\", pinned: false, category: \"urgent\" },\n];","lang":"javascript"},{"k":"code","t":"// src/components/EmptyState.jsx\nexport default function EmptyState() {\n  return <p>No notices yet. Check back later.</p>;\n}","lang":"javascript"},{"k":"code","t":"// src/components/NoticeList.jsx\nimport NoticeCard from \"./NoticeCard\";\nimport EmptyState from \"./EmptyState\";\n\nexport default function NoticeList({ notices }) {\n  if (notices.length === 0) return <EmptyState />;\n  return (\n    <section>","lang":"javascript"},{"k":"code","t":"      {notices.map((n) => (\n        <NoticeCard key={n.id} {...n} />\n      ))}\n    </section>\n  );\n}","lang":"javascript"},{"k":"callout","t":"Replace the placeholder in App.jsx with <NoticeList notices={notices} />. You should see three cards. Open the Console: there must be no warning about keys. The key lets React tell items apart, and it must be a stable id, not the array index."}],"id":"write-noticelist-and-emptystate"},{"title":"Add category labels","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["In NoticeCard, add category to the props and show <span className={\"label \" + category}>{category}</span> under the title.",false]],[["In App.css give .label.academic, .label.events and .label.urgent three different background colours.",false]],[["Each card should now show a coloured label.",false]]]}],"extra":["(Skip this step if you are behind.)"],"id":"add-category-labels"},{"title":"Style the page","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["Write your styles in src/App.css and import it at the top of App.jsx with import \"./App.css\";.",false]],[["Give .notice a border, padding and a margin, and centre main with max-width: 700px; margin: 0 auto;.",false]]]}],"id":"style-the-page"},{"title":"Test the empty state","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"list","items":[[["In App.jsx change the call to <NoticeList notices={[]} />.",false]],[["You should see \"No notices yet.\" Change it back and take your screenshot.",false]]]}],"id":"test-the-empty-state"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["The page has Header, NoticeCard, NoticeList, EmptyState and Footer components, each in its own file.",false]],[["The list uses map with a key, and the Console shows no warnings.",false]],[["The empty state appears when the array is empty.",false]],[["You have the screenshot, and you can explain in one sentence what a prop is.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Build a filter bar that is purely visual: render three category buttons and highlight the one whose name is passed in as a prop called active. In Week 13 you will make it interactive."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"slideCount":19,"pptx":"downloads/laboratory/Week_12_Laboratory_React_components_and_props.pptx"},{"week":13,"title":"Notice form","focus":"notice form with local state","duration":"3 hours","file":"Week_13_Laboratory_React_state_events_and_controlled_forms.pptx","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Make your static interface from Week 12 interactive, using only local state. There is still no server.",false]],[["Deliverable. ",true],["A page where the user can post a notice, search the list, and delete a notice, with form validation messages.",false]]]}],"extra":["When your page does not update, ask: did I call the setter, and did I give it a new array or object?"],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: notice form with local state","tag":null,"kind":"divider","sub":"Work in your Week 12 project.","id":"step-by-step-guide-notice-form-with-local-state"},{"title":"Move the notices into state","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"list","items":[[["In App.jsx, delete the top-level notices constant and keep the data as the starting value:",false]]]},{"k":"code","t":"import { useState } from \"react\";\n\nconst initialNotices = [ /* your three notices from Week 12 */ ];\n\nexport default function App() {\n  const [notices, setNotices] = useState(initialNotices);\n  // ...\n  return (\n    <>","lang":"javascript"},{"k":"code","t":"      <Header />\n      <main><NoticeList notices={notices} /></main>\n      <Footer />\n    </>\n  );\n}","lang":"xml"},{"k":"callout","t":"The page should look exactly as it did before. If it does, state is wired correctly."}],"id":"move-the-notices-into-state"},{"title":"Build NoticeForm with controlled inputs","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"code","t":"// src/components/NoticeForm.jsx\nimport { useState } from \"react\";\n\nexport default function NoticeForm({ onAdd }) {\n  const [title, setTitle] = useState(\"\");\n  const [message, setMessage] = useState(\"\");\n\n  function handleSubmit(e) {\n    e.preventDefault(); // stop the page from reloading\n    onAdd({ title, message });\n    setTitle(\"\");\n    setMessage(\"\");\n  }","lang":"javascript"},{"k":"code","t":"  return (\n    <form onSubmit={handleSubmit}>\n      <input value={title} onChange={(e) => setTitle(e.target.value)} placeholder=\"Title\" />\n      <textarea value={message} onChange={(e) => setMessage(e.target.value)} placeholder=\"Message\" />\n      <button type=\"submit\">Post notice</button>\n    </form>\n  );\n}","lang":"xml"},{"k":"callout","t":"In App.jsx add the handler and the form:"},{"k":"code","t":"function handleAdd({ title, message }) {\n  const notice = {\n    id: Date.now(), // temporary id; the server gives the real one in Week 15\n    title,\n    message,\n    createdAt: new Date().toISOString(),\n    pinned: false,\n    category: \"general\",\n  };\n  setNotices([notice, ...notices]); // a NEW array, newest first\n}","lang":"javascript"},{"k":"callout","t":"Put <NoticeForm onAdd={handleAdd} /> above the list. Type a title and message and press the button. You should see the new card at the top and the form clear. Typing in the boxes should feel normal, because every keystroke updates state."}],"id":"build-noticeform-with-controlled-inputs"},{"title":"Add validation messages","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"list","items":[[["In NoticeForm, add const [error, setError] = useState(\"\"); and change handleSubmit:",false]]]},{"k":"code","t":"function handleSubmit(e) {\n  e.preventDefault();\n  if (title.trim() === \"\" || message.trim() === \"\") {\n    setError(\"Title and message are both required.\");\n    return;\n  }\n  setError(\"\");\n  onAdd({ title: title.trim(), message: message.trim() });\n  setTitle(\"\");","lang":"javascript"},{"k":"code","t":"  setMessage(\"\");\n}","lang":"javascript"},{"k":"callout","t":"Show it with {error && <p role=\"alert\">{error}</p>} above the button. Submit an empty form and you should see the message and no new card. Submit a good one and the message disappears."}],"id":"add-validation-messages"},{"title":"Add delete","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["In App.jsx:",false]]]},{"k":"code","t":"function handleDelete(id) {\n  setNotices(notices.filter((n) => n.id !== id));\n}","lang":"javascript"},{"k":"list","items":[[["Pass it down: <NoticeList notices={notices} onDelete={handleDelete} />.",false]]]},{"k":"list","items":[[["In NoticeList accept onDelete and give each card onDelete={() => onDelete(n.id)}.",false]],[["In NoticeCard accept onDelete and add <button onClick={onDelete}>Delete</button>.",false]]]}],"extra":["Click Delete on a card and it should vanish. Notice the data flows down as props and the event flows up through a function."],"id":"add-delete"},{"title":"Add search as derived data","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["In App.jsx add const [search, setSearch] = useState(\"\"); and compute the list to show.",false]],[["Do not store the filtered list in state:",false]]]},{"k":"code","t":"const visible = notices.filter((n) =>\n  n.title.toLowerCase().includes(search.toLowerCase())\n);","lang":"javascript"},{"k":"callout","t":"Add <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder=\"Search notices\" /> and pass visible to NoticeList. Type \"lib\" and only matching cards remain. Clear the box and all return. Delete a card while searching and check it still works."}],"id":"add-search-as-derived-data"},{"title":"Add a character counter","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["In NoticeForm, below the textarea, show <small>{message.length} / 500</small> and add maxLength={500} to the textarea.",false]],[["The number should change as you type.",false]],[["(Skip this if you are behind.)",false]]]}],"id":"add-a-character-counter"},{"title":"Test the edge cases","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"table","head":["Try this","You should see"],"rows":[["Submit with only spaces","The validation message"],["Paste 600 characters in the message","Typing stops at 500"],["Delete every notice","The empty state"],["Search for text that matches nothing","The empty state"],["Add two notices quickly","Both appear, newest first"]]},{"k":"list","items":[[["Show your instructor before you leave the lab.",false]]]}],"id":"test-the-edge-cases"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["notices lives in state and the form adds to it using a new array.",false]],[["Empty and space-only input shows a message and adds nothing.",false]],[["Delete and search both work, and search is derived, not stored.",false]],[["You can explain why setNotices([notice, ...notices]) works and notices.push(notice) does not.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Add an edit mode: clicking \"Edit\" on a card turns its title and message into inputs. \"Save\" updates the item with map and a spread, and \"Cancel\" restores the original."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"slideCount":20,"pptx":"downloads/laboratory/Week_13_Laboratory_React_state_events_and_controlled_forms.pptx"},{"week":14,"title":"Fetch a list from your API","focus":"fetch a list from an API","duration":"3 hours","file":"Week_14_Laboratory_React_effects_fetching_loading_and_error.pptx","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Replace the hard-coded notices in your Week 13 page with real data from your own API, which you built on PostgreSQL in Week 11.",false]],[["Deliverable. ",true],["A page that loads notices from your own server, with working loading, error and empty states, a Refresh button, and a screenshot of each state.",false]]]}],"extra":["To see the loading state, add a temporary delay on the server, for example await new Promise((r) => setTimeout(r, 2000)) in the route. Remove it afterwards."],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: fetch notices from your API","tag":null,"kind":"divider","sub":"This guide is the React half of the lab.","id":"step-by-step-guide-fetch-notices-from-your-api"},{"title":"Check the API in Postman","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"list","items":[[["GET http://localhost:3001/api/notices must return 200 and a JSON array.",false]],[["Each notice should have id, title, message, createdAt.",false]],[["If it does not, fix the server before touching React.",false]]]}],"id":"check-the-api-in-postman"},{"title":"Let Vite forward /api to your server","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["In vite.config.js add a proxy so the browser sees one origin and CORS does not get in the way:",false]]]},{"k":"code","t":"import { defineConfig } from \"vite\";\nimport react from \"@vitejs/plugin-react\";\n\nexport default defineConfig({\n  plugins: [react()],\n  server: { proxy: { \"/api\": \"http://localhost:3001\" } },\n});","lang":"javascript"},{"k":"callout","t":"Stop and restart npm run dev in the client (the config is read only at start). You should be able to open http://localhost:5173/api/notices and see the same JSON as in Postman."}],"id":"let-vite-forward-api-to-your-server"},{"title":"Add three pieces of state and fetch in useEffect","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"list","items":[[["In App.jsx:",false]]]},{"k":"code","t":"import { useState, useEffect } from \"react\";\n\nconst [notices, setNotices] = useState([]);\nconst [loading, setLoading] = useState(true);\nconst [error, setError] = useState(null);\n\nuseEffect(() => {\n  fetch(\"/api/notices\")\n    .then((res) => {\n      if (!res.ok) throw new Error(`Server answered ${res.status}`);\n      return res.json();","lang":"javascript"},{"k":"code","t":"    })\n    .then((data) => setNotices(data))\n    .catch((err) => setError(err.message))\n    .finally(() => setLoading(false));\n}, []); // the empty array means: run once, after the first render","lang":"javascript"},{"k":"callout","t":"Show the data with <NoticeList notices={notices} />. You should see your database rows as cards. In the server terminal you should see the request arrive once. If it arrives in an endless loop, you forgot the []."}],"id":"add-three-pieces-of-state-and-fetch-in-useeffect"},{"title":"Render loading, error and empty states","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["Above the main return add early returns:",false]]]},{"k":"code","t":"if (loading) return <p>Loading notices...</p>;\nif (error) return <p role=\"alert\">Could not load notices: {error}</p>;","lang":"xml"},{"k":"callout","t":"NoticeList already shows EmptyState for an empty array. res.ok matters because fetch does not throw on a 404 or 500; without that line a failed request would look like an empty list."}],"id":"render-loading-error-and-empty-states"},{"title":"Fix the keys and the date","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["Make sure NoticeList uses key={n.id} (the real database id), and that the card shows new Date(createdAt).toLocaleString().",false]],[["If the date shows \"Invalid Date\", look at the JSON in Postman: your server must send createdAt, not created_at (use created_at AS \"createdAt\" in the SQL).",false]]]}],"id":"fix-the-keys-and-the-date"},{"title":"Add a Refresh button","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["Move the fetch into a function and call it from both places:",false]]]},{"k":"code","t":"const loadNotices = useCallback(() => {\n  setLoading(true);\n  setError(null);\n  fetch(\"/api/notices\")\n    .then((res) => { if (!res.ok) throw new Error(`Server answered ${res.status}`); return res.json(); })\n    .then(setNotices)\n    .catch((err) => setError(err.message))\n    .finally(() => setLoading(false));\n}, []);","lang":"javascript"},{"k":"code","t":"useEffect(() => { loadNotices(); }, [loadNotices]);","lang":"javascript"},{"k":"callout","t":"(Import useCallback from react.) Add <button onClick={loadNotices}>Refresh</button>. Insert a row in psql, click Refresh, and the new row should appear without reloading the page."}],"id":"add-a-refresh-button"},{"title":"Reproduce each state on purpose and take a screenshot of each","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"table","head":["To get this state","Do this"],"rows":[["Loading","Add await new Promise((r) => setTimeout(r, 2000)) to the server route, reload, then remove it"],["Error","Stop the server and click Refresh"],["Empty","Run DELETE FROM notices; in psql, then Refresh"]]}],"id":"reproduce-each-state-on-purpose-and-take-a-scree"},{"title":"Add a search box (stretch)","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"list","items":[[["Add search state and send it to the server with fetch(\"/api/notices?search=\" + encodeURIComponent(search)).",false]],[["On the server, in getNotices, add the filter:",false]]]},{"k":"code","t":"const { search } = req.query;\nconst { rows } = search\n  ? await db.query(\n      `SELECT id, title, message, created_at AS \"createdAt\" FROM notices WHERE title ILIKE $1 ORDER BY created_at DESC`,\n      [`%${search}%`]\n    )","lang":"javascript"},{"k":"code","t":"  : await db.query(\n      `SELECT id, title, message, created_at AS \"createdAt\" FROM notices ORDER BY created_at DESC`\n    );\nres.json(rows);","lang":"javascript"},{"k":"callout","t":"The $1 placeholder keeps the user's text out of the SQL itself, so it cannot inject SQL."}],"id":"add-a-search-box-stretch"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["The page shows rows from PostgreSQL through your own API.",false]],[["Loading, error and empty states each appear when triggered, and you have three screenshots.",false]],[["The server logs one request per page load, not an endless loop.",false]],[["You can explain why fetch needs the res.ok check.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Replace the ignore flag with an AbortController. Pass its signal to fetch, abort it in the cleanup function, and ignore the resulting AbortError so it does not show as a user-facing error."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"slideCount":24,"pptx":"downloads/laboratory/Week_14_Laboratory_React_effects_fetching_loading_and_error.pptx"},{"week":15,"title":"Connecting React to your API","focus":"Campus Notices Board","duration":"3 hours","file":"Week_15_Laboratory_Connecting_React_to_your_API.pptx","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Build the full-stack Campus Notices Board: an Express API that stores notices and a React page that lists them and posts new ones. This is the culminating lab for the first half of the course.",false]],[["Deliverable. ",true],["A working app plus a Postman screenshot (one success and one 400), a Network-tab screenshot of your POST request, and a completed exit ticket.",false]]]}],"extra":["It is run in three tracks so every student is stretched without being stuck. Your instructor will share the lab handout, the starter repository and the rubric."],"id":"goal-and-deliverable"},{"title":"Where the data lives","tag":"LAB","kind":"brief","blocks":[{"k":"list","items":[[["Tracks A and B keep notices in an array, exactly as in the handout, so the lab stays about the request lifecycle.",false]]]},{"k":"table","head":["Track","What you receive","What you do"],"rows":[["A: Guided","Working GET route and fetch, with blanks in the POST route and the POST fetch","Fill in the blanks, test, then take the stretch step: validation, then loading and error messages"],["B: Standard","The project wiring and TODO comments only","Build both routes with validation, then the React page with loading, empty and error states"],["C: Extension","A layered PostgreSQL project (routes, controllers, db.js, middleware, tests) with TODOs","Build the layered API on PostgreSQL and the React page, then add at least two extensions: full CRUD, tests, search and filter, or optimistic UI"]]},{"k":"table","head":["Segment","Minutes"],"rows":[["Setup and orientation","15"],["Build the API","45"],["Test the API in Postman","15"],["Break","10"],["Build the React client","60"],["Checkpoint demo: show the Network tab and explain one request","20"],["Exit ticket and reflection","15"]]},{"k":"list","items":[[["Test every server step in Postman before you touch React.",false]]]},{"k":"list","items":[[["You may move between tracks at any time.",false]],[["Moving up when it feels easy is encouraged, and moving down to get unstuck is never a penalty.",false]]]}],"extra":["Track C builds on PostgreSQL from the start: the starter gives you db.js and schema.sql, you write the controllers with the parameterized-query pattern from Week 11, and the board runs as a true PERN app. If you finish early in Track A or B, moving your notices into the PostgreSQL table is the best next step."],"id":"where-the-data-lives"},{"title":"A step-by-step path for every track","tag":"LAB","kind":"brief","blocks":[{"k":"list","items":[[["The handout gives each track its own numbered guide, with what to do, what you should see, and a checkpoint after each part.",false]],[["The path is the same shape in all three:",false]],[["Start the server and see it respond (Track A reads a finished GET route; Tracks B and C write it).",false]],[["Build the POST route with validation (Track A fills in the blanks first and adds validation as a stretch).",false]]]},{"k":"list","items":[[["Test every server route in Postman and write down each status code. Take a screenshot of one 201 and one 400. Checkpoint 1.",false]],[["Build or finish the React page: state, loading on first render, the form, and the list.",false]],[["Break it on purpose: stop the server and confirm the page explains the problem instead of going blank.",false]],[["Open the Network tab, find your POST request, and explain its status code and payload. Checkpoint 2.",false]]]},{"k":"list","items":[[["Track C only: add at least two extensions (full CRUD, tests, search and filter, or optimistic UI).",false]]]}],"id":"a-step-by-step-path-for-every-track"},{"title":"Step-by-step guide: Week 15 checkpoints","tag":null,"kind":"divider","sub":"The handout has the full numbered guide for your track.","id":"step-by-step-guide-week-13-checkpoints"},{"title":"Set up (15 minutes)","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"list","items":[[["Pick your track, copy the starter for it, and run npm install in both the server and client folders.",false]],[["Create .env from .env.example (Track C: also run db/schema.sql in your campus_notices database).",false]],[["Start the server with npm run dev.",false]]]}],"extra":["Step 1 (15 minutes). You should see API on http://localhost:3001, and GET /api/health (or GET /api/notices) should answer in Postman."],"id":"set-up-15-minutes"},{"title":"Build the API (45 minutes)","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["Write the routes in the order GET, then POST with validation.",false]],[["After each one, test it in Postman.",false]],[["Track C writes them as controllers using db.query with $1 placeholders, RETURNING, and created_at AS \"createdAt\".",false]]]}],"extra":["Step 2 (45 minutes)."],"id":"build-the-api-45-minutes"},{"title":"Test every server route (15 minutes)","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"list","items":[[["Send a good POST (201), an empty title (400) and a missing body (400).",false]],[["Write down every status code and take your screenshot of one 201 and one 400.",false]],[["Checkpoint 1: do not open React until this passes.",false]]]}],"extra":["Step 3 (15 minutes)."],"id":"test-every-server-route-15-minutes"},{"title":"Build the client (60 minutes)","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["State first, then useEffect with loading and error states, then the form that POSTs, then the list.",false]],[["Test in the browser after each part.",false]]]}],"extra":["Step 4 (60 minutes)."],"id":"build-the-client-60-minutes"},{"title":"Checkpoint demo (20 minutes)","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["Open the Network tab, send a POST from the page, and explain its method, URL, payload and status code to your instructor.",false]],[["Checkpoint 2.",false]]]}],"extra":["Step 5 (20 minutes)."],"id":"checkpoint-demo-20-minutes"},{"title":"Exit ticket (15 minutes)","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["Complete the exit ticket and reflection honestly.",false]]]}],"extra":["Step 6 (15 minutes)."],"id":"exit-ticket-15-minutes"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["The API passes the Postman checks with correct status codes.",false]],[["The page shows loading, empty and error states and can post a notice.",false]],[["You have both screenshots and your exit ticket.",false]],[["Track C: at least two extensions are working.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Add optimistic updates: show the new notice in the list instantly with a temporary label, then replace it with the server's version when the response arrives. If the server rejects it, remove it and show the error."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"slideCount":17,"pptx":"downloads/laboratory/Week_15_Laboratory_Connecting_React_to_your_API.pptx"},{"week":16,"title":"Authentication and authorization basics","focus":"add login to the Notices Board","duration":"3 hours","file":"Week_16_Laboratory_Authentication_and_authorization_basics.pptx","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Add registration and login to your Notices Board so that only logged-in users can post, and only admins can delete.",false]],[["Deliverable. ",true],["A working app with register, login and logout, a protected POST route, an admin-only DELETE route, and a Postman collection that proves each rule.",false]]]}],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: login, protected routes and roles","tag":null,"kind":"divider","sub":"Build the server side first (Steps 1 to 6) and test it fully in Postman.","id":"step-by-step-guide-login-protected-routes-and-ro"},{"title":"Install and configure","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"code","t":"npm install bcryptjs jsonwebtoken","lang":"bash"},{"k":"callout","t":"Add a long random secret to .env (never commit it). You can generate one with node -e \"console.log(require('crypto').randomBytes(32).toString('hex'))\"."},{"k":"code","t":"# .env\nJWT_SECRET=paste-the-long-random-string-here","lang":"javascript"}],"id":"install-and-configure"},{"title":"Create the users table","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["Save this as db/auth.sql and run it with psql -U postgres -d campus_notices -f db/auth.sql:",false]]]},{"k":"code","t":"CREATE TABLE IF NOT EXISTS users (\n  id            SERIAL PRIMARY KEY,\n  name          TEXT NOT NULL,\n  email         TEXT NOT NULL UNIQUE,\n  password_hash TEXT NOT NULL,\n  role          TEXT NOT NULL DEFAULT 'student' CHECK (role IN ('student', 'admin')),\n  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()\n);","lang":"javascript"},{"k":"code","t":"\nALTER TABLE notices ADD COLUMN IF NOT EXISTS author_id INTEGER REFERENCES users(id);","lang":"javascript"},{"k":"callout","t":"Run \\d users in psql. You should see the five columns and a UNIQUE index on email. UNIQUE is what stops two accounts sharing an email, even if two people register at the same instant."}],"id":"create-the-users-table"},{"title":"Write the user model and the register and login controllers","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"code","t":"// models/User.js\nconst db = require(\"../db\");\n\nexports.findByEmail = async (email) => {\n  const { rows } = await db.query(\"SELECT * FROM users WHERE email = $1\", [email.toLowerCase()]);\n  return rows[0]; // undefined when there is no such user\n};\n\nexports.create = async ({ name, email, passwordHash }) => {\n  const { rows } = await db.query(\n    `INSERT INTO users (name, email, password_hash)\n     VALUES ($1, $2, $3)\n     RETURNING id, name, email, role`,","lang":"javascript"},{"k":"code","t":"    [name, email.toLowerCase(), passwordHash]\n  );\n  return rows[0];\n};","lang":"javascript"},{"k":"code","t":"// controllers/authController.js\nconst bcrypt = require(\"bcryptjs\");\nconst jwt = require(\"jsonwebtoken\");\nconst User = require(\"../models/User\");\nconst asyncHandler = require(\"../middleware/asyncHandler\");\n\nconst signToken = (user) =>","lang":"javascript"},{"k":"code","t":"  jwt.sign({ sub: user.id, role: user.role }, process.env.JWT_SECRET, { expiresIn: \"2h\" });\n\nconst publicUser = ({ id, name, email, role }) => ({ id, name, email, role });\n\nexports.register = asyncHandler(async (req, res) => {\n  const { name, email, password } = req.body;\n  if (!name || !email || !password || password.length < 8) {\n    return res.status(400).json({ error: \"Name, email and a password of 8 or more characters are required.\" });\n  }\n  if (await User.findByEmail(email)) {","lang":"javascript"},{"k":"code","t":"    return res.status(409).json({ error: \"That email is already registered.\" });\n  }\n  const passwordHash = await bcrypt.hash(password, 10);\n  const user = await User.create({ name, email, passwordHash });\n  res.status(201).json({ token: signToken(user), user: publicUser(user) });\n});\n\nexports.login = asyncHandler(async (req, res) => {\n  const { email, password } = req.body;\n  const user = email && (await User.findByEmail(email));\n  const ok = user && password && (await bcrypt.compare(password, user.password_hash));","lang":"javascript"},{"k":"code","t":"  if (!ok) {\n    return res.status(401).json({ error: \"Invalid email or password.\" });\n  }\n  res.json({ token: signToken(user), user: publicUser(user) });\n});","lang":"javascript"},{"k":"callout","t":"Create routes/auth.js with router.post(\"/register\", register) and router.post(\"/login\", login), and in app.js add app.use(\"/api/auth\", authRoutes); above the 404 handler."},{"k":"list","items":[[["Postman check:",false]]]},{"k":"list","items":[[["POST /api/auth/register with name, email and an 8-character password returns 201 with a token and a user that has no password_hash.",false]],[["Run SELECT email, password_hash FROM users; in psql: the hash must look like $2a$10$..., never the real password.",false]]]}],"id":"write-the-user-model-and-the-register-and-login-"},{"title":"Write requireAuth and requireRole","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"code","t":"// middleware/auth.js\nconst jwt = require(\"jsonwebtoken\");\n\nexports.requireAuth = (req, res, next) => {\n  const [type, token] = (req.headers.authorization || \"\").split(\" \");\n  if (type !== \"Bearer\" || !token) {\n    return res.status(401).json({ error: \"Please log in.\" });\n  }\n  try {\n    const payload = jwt.verify(token, process.env.JWT_SECRET);\n    req.user = { id: payload.sub, role: payload.role };\n    next();\n  } catch {","lang":"javascript"},{"k":"code","t":"    res.status(401).json({ error: \"Your session is invalid or has expired.\" });\n  }\n};\n\nexports.requireRole = (role) => (req, res, next) =>\n  req.user && req.user.role === role\n    ? next()\n    : res.status(403).json({ error: \"You are not allowed to do that.\" });","lang":"javascript"}],"id":"write-requireauth-and-requirerole"},{"title":"Protect the routes","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["In routes/notices.js:",false]]]},{"k":"code","t":"const { requireAuth, requireRole } = require(\"../middleware/auth\");\n\nrouter.get(\"/\", c.getNotices);                                        // public\nrouter.post(\"/\", requireAuth, c.createNotice);                        // any logged-in user\nrouter.delete(\"/:id\", requireAuth, requireRole(\"admin\"), c.deleteNotice); // admin only","lang":"javascript"},{"k":"callout","t":"Also save the author: in createNotice add author_id as a fourth column with req.user.id as the fourth parameter, in the same parameterized INSERT. The foreign key refuses an id that does not exist in users."}],"id":"protect-the-routes"},{"title":"Test every rule in Postman","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["In Postman choose the Authorization tab, type Bearer Token, and paste the token from login.",false]],[["To test the admin rule, make yourself an admin in psql:",false]]]},{"k":"table","head":["Request","Expected"],"rows":[["POST /api/notices with no token","401"],["POST /api/notices with a bad token (change a character)","401"],["POST /api/notices as a student","201"],["DELETE /api/notices/1 as a student","403"],["DELETE /api/notices/1 as an admin","204"],["POST /api/auth/login with a wrong password","401, same message as an unknown email"],["POST /api/auth/register with an email already used","409"]]},{"k":"list","items":[[["Save these requests in your Postman collection.",false]]]}],"extra":["UPDATE users SET role = 'admin' WHERE email = 'you@example.com';, then log in again to get a new token (the role is inside the token, so an old token still says student)."],"id":"test-every-rule-in-postman"},{"title":"Build the login and register forms","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"list","items":[[["Create AuthForm.jsx with email, password and (for register) name inputs as controlled inputs, a mode prop (\"login\" or \"register\") and an onAuth prop.",false]],[["On submit, send a POST to \"/api/auth/\" + mode with the header Content-Type: application/json and the body JSON.stringify(values).",false]]]}],"extra":["Check res.ok, and show data.error if it fails. On success, call onAuth(data)."],"id":"build-the-login-and-register-forms"},{"title":"Keep the token","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"list","items":[[["In App.jsx:",false]]]},{"k":"code","t":"const [token, setToken] = useState(() => localStorage.getItem(\"token\"));\n\nfunction handleLogin({ token }) {\n  localStorage.setItem(\"token\", token);\n  setToken(token);\n}\nfunction handleLogout() {\n  localStorage.removeItem(\"token\");\n  setToken(null);\n}","lang":"javascript"},{"k":"callout","t":"Show <AuthForm onAuth={handleLogin} mode=\"login\" /> when token is null, and a Logout button when it is set. Log in, refresh the page, and you should stay logged in."}],"id":"keep-the-token"},{"title":"Send the token and hide the form","tag":"STEP 9","kind":"step","step":9,"blocks":[{"k":"list","items":[[["Show NoticeForm only when token exists.",false]],[["In the POST request add the header Authorization with the value \"Bearer \" + token, and if the response status is 401 call handleLogout().",false]]]}],"extra":["log out and the post form disappears; log in, post a notice, and see it in the list. Open the Network tab and confirm the request has the Authorization header. Remember that hiding the form is only convenience: Step 6 proved the real protection is on the server."],"id":"send-the-token-and-hide-the-form"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["Passwords are stored as hashes, and no response contains password_hash.",false]],[["The Postman table above passes, including 401 versus 403.",false]],[["You stay logged in after a refresh, and logout works.",false]],[["You can explain the difference between 401 and 403 and why the role check must be on the server.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Make notices deletable by their author as well as by admins. Then write a short comparison, with one paragraph each, of localStorage and httpOnly cookies for storing a token. Name one attack each approach is more exposed to."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"slideCount":24,"pptx":"downloads/laboratory/Week_16_Laboratory_Authentication_and_authorization_basics.pptx"},{"week":17,"title":"Testing, environment variables and deployment","focus":"test and deploy the Notices Board","duration":"3 hours","file":"Week_17_Laboratory_Testing_environment_variables_and_deploy.pptx","sections":[{"title":"Goal and deliverable","tag":"LAB BRIEF","kind":"brief","blocks":[{"k":"list","items":[[["Goal. ",true],["Add automated tests to your Notices Board, move its configuration into environment variables, and put it on the internet.",false]],[["Deliverable. ",true],["At least five passing tests, a .env.example, a production build served by Express, and a live URL (or, if hosting is unavailable, a screenshot of the production build running locally).",false]]]}],"extra":["If your deployed site shows a blank page, open the browser console and the Network tab first. The first red error nearly always names the problem."],"id":"goal-and-deliverable"},{"title":"Step-by-step guide: test and deploy","tag":null,"kind":"divider","sub":"Do the tests first (Steps 1 to 4), then configuration (Step 5), then the production build (Step 6), and deploy last (Steps 7 and 8).","id":"step-by-step-guide-test-and-deploy"},{"title":"Install the tools and make a test database","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"code","t":"npm install --save-dev jest supertest\ncreatedb -U postgres campus_notices_test\npsql -U postgres -d campus_notices_test -f db/schema.sql\npsql -U postgres -d campus_notices_test -f db/auth.sql","lang":"bash"},{"k":"callout","t":"In package.json set \"test\": \"jest --runInBand\". Add the test database address to .env:"},{"k":"code","t":"DATABASE_TEST_URL=postgres://postgres:yourpassword@localhost:5432/campus_notices_test","lang":"bash"},{"k":"callout","t":"Use the same psql commands for every schema file you have created. You should be able to run psql -U postgres -d campus_notices_test -c \"\\dt\" and see notices and users."}],"id":"install-the-tools-and-make-a-test-database"},{"title":"Teach db.js to choose the right database","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["Jest sets NODE_ENV to test by itself.",false]]]},{"k":"code","t":"// db.js\nrequire(\"dotenv\").config();\nconst { Pool } = require(\"pg\");\n\nconst isTest = process.env.NODE_ENV === \"test\";\nconst pool = new Pool({\n  connectionString: isTest ? process.env.DATABASE_TEST_URL : process.env.DATABASE_URL,\n  ssl: process.env.NODE_ENV === \"production\" ? { rejectUnauthorized: false } : false,\n});","lang":"javascript"},{"k":"code","t":"\nmodule.exports = {\n  query: (text, params) => pool.query(text, params),\n  pool,\n};","lang":"javascript"},{"k":"callout","t":"Confirm that app.js exports the app and only server.js calls listen. Supertest needs that split."}],"id":"teach-db-js-to-choose-the-right-database"},{"title":"Write the tests","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"list","items":[[["Create tests/notices.test.js:",false]]]},{"k":"code","t":"const request = require(\"supertest\");\nconst app = require(\"../app\");\nconst db = require(\"../db\");\n\nlet token;\n\nbeforeEach(async () => {\n  await db.query(\"TRUNCATE notices, users RESTART IDENTITY CASCADE\");\n  const body = { name: \"Test\", email: \"test@example.com\", password: \"password123\" };\n  const res = await request(app).post(\"/api/auth/register\").send(body);","lang":"javascript"},{"k":"code","t":"  token = res.body.token;\n});\n\nafterAll(async () => {\n  await db.pool.end(); // lets Jest exit cleanly\n});\n\ndescribe(\"POST /api/notices\", () => {\n  test(\"creates a notice and returns 201\", async () => {\n    const res = await request(app)\n      .post(\"/api/notices\")\n      .set(\"Authorization\", `Bearer ${token}`)\n      .send({ title: \"Hello\", message: \"World\" });\n    expect(res.status).toBe(201);","lang":"javascript"},{"k":"code","t":"    expect(res.body.title).toBe(\"Hello\");\n  });\n\n  test(\"rejects an empty title with 400\", async () => {\n    const res = await request(app)\n      .post(\"/api/notices\")\n      .set(\"Authorization\", `Bearer ${token}`)\n      .send({ title: \"\", message: \"World\" });\n    expect(res.status).toBe(400);\n    expect(res.body.error).toBeDefined();\n  });\n\n  test(\"rejects a request with no token with 401\", async () => {","lang":"javascript"},{"k":"code","t":"    const res = await request(app).post(\"/api/notices\").send({ title: \"Hi\", message: \"There\" });\n    expect(res.status).toBe(401);\n  });\n});\n\ndescribe(\"GET /api/notices\", () => {\n  test(\"returns the list\", async () => {\n    await request(app).post(\"/api/notices\").set(\"Authorization\", `Bearer ${token}`).send({ title: \"A\", message: \"B\" });\n    const res = await request(app).get(\"/api/notices\");\n    expect(res.status).toBe(200);\n    expect(res.body).toHaveLength(1);\n  });","lang":"javascript"},{"k":"code","t":"});\n\ndescribe(\"DELETE /api/notices/:id\", () => {\n  test(\"a student cannot delete (403)\", async () => {\n    const created = await request(app).post(\"/api/notices\").set(\"Authorization\", `Bearer ${token}`).send({ title: \"A\", message: \"B\" });\n    const res = await request(app).delete(`/api/notices/${created.body.id}`).set(\"Authorization\", `Bearer ${token}`);\n    expect(res.status).toBe(403);\n  });\n});","lang":"javascript"}],"id":"write-the-tests"},{"title":"Run the tests, then break something","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["Run npm test.",false]],[["You should see five passing tests.",false]],[["Now change the 400 check in your controller to return 200, run again, and read the failing test output: it names the test, the expected value and the received value.",false]]]}],"extra":["Undo the change and see all tests pass. If Jest says \"did not exit\", you forgot pool.end(). If your tests touch real notices, NODE_ENV is not test: check the isTest line."],"id":"run-the-tests-then-break-something"},{"title":"Move every setting into environment variables","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["Search your code for anything that differs between your laptop and a live server: the port (process.env.PORT || 3001), the database address, JWT_SECRET, and the allowed website in CORS (process.env.CLIENT_URL).",false]],[["Then write .env.example with fake values and commit it.",false]],[["Confirm .env is ignored by Git:",false]]]},{"k":"code","t":"# .env.example\nPORT=3001\nDATABASE_URL=postgres://user:password@localhost:5432/campus_notices\nDATABASE_TEST_URL=postgres://user:password@localhost:5432/campus_notices_test\nJWT_SECRET=change-me-to-a-long-random-string\nCLIENT_URL=http://localhost:5173","lang":"javascript"},{"k":"callout","t":"Run git status. .env must not appear in the list."}],"id":"move-every-setting-into-environment-variables"},{"title":"Build the client and serve it from Express","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"code","t":"cd client\nnpm run build","lang":"bash"},{"k":"list","items":[[["You should see a dist folder.",false]],[["In app.js, above the 404 handler, add the production block from the lecture so Express serves dist and returns index.html for other routes.",false]],[["Run the server with NODE_ENV=production node server.js and open http://localhost:3001.",false]]]}],"extra":["The whole app should work from one address with no Vite running. Take this screenshot: it is your fallback if deployment fails."],"id":"build-the-client-and-serve-it-from-express"},{"title":"Push to GitHub and deploy","tag":"STEP 7","kind":"step","step":7,"blocks":[{"k":"list","items":[[["Make sure .gitignore contains node_modules, .env and dist.",false]],[["Then:",false]]]},{"k":"code","t":"git add .\ngit commit -m \"Notices Board ready for deployment\"\ngit push","lang":"bash"},{"k":"list","items":[[["On your host, create a new web service from the repository, set the build command and start command from your root package.json, and add each variable from .env.example (with real values) in the host's dashboard.",false]]]}],"extra":["Create a hosted PostgreSQL database, run db/schema.sql and db/auth.sql on it, and put its connection string in DATABASE_URL."],"id":"push-to-github-and-deploy"},{"title":"Test the live site","tag":"STEP 8","kind":"step","step":8,"blocks":[{"k":"list","items":[[["Open the live address with the Network tab open.",false]],[["Go through every feature: list, register, login, post, delete as admin, logout.",false]],[["Add a GET /api/health route and open it to confirm the app is alive.",false]]]}],"extra":["Write down anything that fails. A blank page almost always has a red error in the Console that names the cause. A free host may take up to a minute to wake up on the first request."],"id":"test-the-live-site"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["npm test shows at least five passing tests, and you have seen one fail on purpose.",false]],[[".env.example exists, and .env is not in Git.",false]],[["The production build works locally from Express at one address.",false]],[["You have a live URL (or the local production screenshot) and a list of any problems.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Add a GitHub Actions workflow that runs your tests on every push. It needs to start a PostgreSQL service (a services: postgres block), create the tables from your schema files, install dependencies, and run npm test. Add the build status badge to your README."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"slideCount":21,"pptx":"downloads/laboratory/Week_17_Laboratory_Testing_environment_variables_and_deploy.pptx"},{"week":18,"title":"Final project presentations and demos","focus":"demos","duration":"3 hours","file":"Week_18_Laboratory_Final_project_presentations_and_demos.pptx","sections":[{"title":"Overview","tag":"LAB","kind":"brief","blocks":[{"k":"list","items":[[["Use the lab for the remaining presentations, for peer feedback, and for a final round of questions.",false]],[["While one team presents, everyone else completes a peer feedback form.",false]]]},{"k":"table","head":["Peer feedback question","Scale"],"rows":[["The problem and users were clearly explained","1 to 5"],["The demo worked and showed the main journey","1 to 5"],["The team could explain how it works underneath","1 to 5"],["One thing that impressed me","A sentence"],["One thing I would improve","A sentence"]]}],"id":"overview"},{"title":"How your project is assessed (100 points)","tag":"LAB","kind":"brief","blocks":[{"k":"table","head":["Criterion","Points","What the instructor looks for"],"rows":[["Problem and scope","10","A real problem, a sensible scope, and clear users"],["Technical depth","25","A sound PERN design: REST routes, a well-chosen table design (keys, constraints, foreign keys), authentication and authorization, validation"],["Working product and demo","25","The core journey works live, errors are handled, and the interface is usable"],["Code quality and security habits","15","Clear structure, no secrets in the repository, passwords hashed, input validated"],["Testing and deployment","10","Automated tests that pass, and a live or reproducible deployment"],["Presentation and teamwork","10","Clear, well-timed, and everybody contributes"],["Individual understanding","5","Each member answers a question about the code"],["Total","100",""]]},{"k":"list","items":[[["Your instructor may adjust marks for individual contribution after reading the repository history and the peer feedback.",false]]]}],"id":"how-your-project-is-assessed-100-points"},{"title":"Step-by-step guide: demo day","tag":null,"kind":"divider","sub":"This lab is for presenting and learning from each other.","id":"step-by-step-guide-demo-day"},{"title":"One day before: freeze and rehearse","tag":"STEP 1","kind":"step","step":1,"blocks":[{"k":"list","items":[[["Stop adding features.",false]],[["Fix only bugs that break the main journey.",false]],[["Run npm test, then open the live site (or your local production build) and walk through your demo from a fresh browser window with no one logged in.",false]]]}],"id":"one-day-before-freeze-and-rehearse"},{"title":"Prepare your demo","tag":"STEP 2","kind":"step","step":2,"blocks":[{"k":"list","items":[[["Write the five-minute script on paper: the problem in one sentence, the main user journey (three to five clicks), one error case you handle on purpose, and one thing you would build next.",false]],[["Decide who speaks for each part so everyone contributes.",false]]]}],"extra":["Have a backup ready (screenshots or a short screen recording) in case the network fails."],"id":"prepare-your-demo"},{"title":"Prepare to explain what is underneath","tag":"STEP 3","kind":"step","step":3,"blocks":[{"k":"list","items":[[["Each member must be able to answer a question about the code.",false]],[["Practise answering these aloud:",false]],[["What happens, step by step, when a user posts a notice?",false]]]}],"extra":["Where is the password checked, and how is it stored? Which rule of your table design stops bad data? What would break if the token were missing?"],"id":"prepare-to-explain-what-is-underneath"},{"title":"Demo order checklist","tag":"STEP 4","kind":"step","step":4,"blocks":[{"k":"list","items":[[["Before you present:",false]],[["Database seeded with a few realistic notices and at least one admin user.",false]],[["Server running and GET /api/health returns 200.",false]],[["Browser zoomed so the back row can read it, with the Network tab ready.",false]],[["Repository open on a second tab, in case someone asks to see code.",false]]]}],"id":"demo-order-checklist"},{"title":"While another team presents","tag":"STEP 5","kind":"step","step":5,"blocks":[{"k":"list","items":[[["Complete the peer feedback form below for every team.",false]],[["Score honestly, and write one specific thing that impressed you and one specific improvement.",false]],[["A sentence like \"the empty state was clear\" is more useful than \"good job\".",false]]]}],"id":"while-another-team-presents"},{"title":"After your own demo","tag":"STEP 6","kind":"step","step":6,"blocks":[{"k":"list","items":[[["Write down every question you were asked and whether you could answer it.",false]],[["Read your peer feedback.",false]],[["Pick one improvement and note how you would make it.",false]]]}],"id":"after-your-own-demo"},{"title":"You are done when","tag":"CHECKLIST","kind":"checklist","blocks":[{"k":"list","items":[[["You presented a working demo within the time limit, and every member spoke.",false]],[["You completed a peer feedback form for every other team.",false]],[["Your repository has no secrets, and its README explains how to run it.",false]],[["You have written down your one next improvement.",false]]]}],"id":"you-are-done-when"},{"title":"Challenge problem (optional)","tag":"FINISHED EARLY?","kind":"challenge","blocks":[{"k":"callout","t":"Write a one-page post-mortem of your project. Describe what went well, the hardest bug and how you found it, one decision you would reverse, and one thing you learned about working as a team."}],"id":"challenge-problem-optional"}],"quiz":[],"refs":[],"refsIntro":null,"slideCount":13,"pptx":"downloads/laboratory/Week_18_Laboratory_Final_project_presentations_and_demos.pptx"}];